-- ===== CYRIS ANIME BG (embedded) =====
local CYRIS_BG_B64 = [[]]
local function cyrisDecodeB64(data)
	local ok, res = pcall(function()
		if crypt and crypt.base64decode then return crypt.base64decode(data) end
		if crypt and crypt.base64_decode then return crypt.base64_decode(data) end
		if base64_decode then return base64_decode(data) end
		if syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then
			return syn.crypt.base64.decode(data)
		end
		-- pure Lua fallback (small alphabet)
		local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
		data = data:gsub('[^'..b..'=]', '')
		return (data:gsub('.', function(x)
			if x == '=' then return '' end
			local r, f = '', (b:find(x) - 1)
			for i = 6, 1, -1 do r = r .. (f % 2^i - f % 2^(i-1) > 0 and '1' or '0') end
			return r
		end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
			if #x ~= 8 then return '' end
			local c = 0
			for i = 1, 8 do c = c + (x:sub(i, i) == '1' and 2^(8 - i) or 0) end
			return string.char(c)
		end))
	end)
	if ok and res then return res end
	return nil
end

local function ensureCyrisBgFile()
	local names = {"cyris_bg.jpg", "cyris_menu_bg.jpg"}
	for _, n in ipairs(names) do
		local ok = pcall(function()
			if isfile and isfile(n) then return true end
		end)
		-- always rewrite so the embedded art is used
	end
	local bin = cyrisDecodeB64(CYRIS_BG_B64)
	if not bin then
		warn("[CYRIS] Failed to decode embedded anime bg")
		return nil
	end
	local fname = "cyris_bg.jpg"
	local wok = pcall(function()
		if writefile then writefile(fname, bin) end
	end)
	if not wok then
		warn("[CYRIS] writefile failed for bg")
		return nil
	end
	local asset = nil
	pcall(function()
		if getcustomasset then asset = getcustomasset(fname) end
		if not asset and syn and syn.getcustomasset then asset = syn.getcustomasset(fname) end
		if not asset and getsynasset then asset = getsynasset(fname) end
	end)
	return asset
end

local CYRIS_ANIME_BG = ensureCyrisBgFile()
