local function pick(t) 
    return t[math.random(1, #t)] 
end 
 
local function findPlayer(name) 
    if not name then return nil end
    name = string.lower(name) 
    for _, p in pairs(Players:GetPlayers()) do 
        if string.lower(p.Name) == name or string.lower(p.DisplayName) == name then 
            return p 
        end 
    end 
    return nil
end

-- ==================== EVENT SYSTEM ====================
local function createEvent()
    if eventData then
        if eventData.model then eventData.model:Destroy() end
        if eventData.sound then eventData.sound:Destroy() end
        if eventData.connection then eventData.connection:Disconnect() end
        eventData = nil
    end
    
    local character = LocalPlayer.Character
    if not character then return "No body to claim..." end
    
    local giant = character:Clone()
    if not giant then return "The copy could not be born." end
    
    for _, obj in pairs(giant:GetDescendants()) do
        if obj:IsA("Script") or obj:IsA("LocalScript") or obj:IsA("ScreenGui") or obj:IsA("BillboardGui") then
            obj:Destroy()
        end
    end
    
    local humanoid = giant:FindFirstChildOfClass("Humanoid")
    if humanoid then
        humanoid.DisplayName = "GIANT " .. LocalPlayer.DisplayName
        pcall(function()
            humanoid.BodyDepthScale.Value = 5
            humanoid.BodyHeightScale.Value = 5
            humanoid.BodyWidthScale.Value = 5
            humanoid.HeadScale.Value = 5
        end)
    end
    
    local root = character:FindFirstChild("HumanoidRootPart")
    local giantRoot = giant:FindFirstChild("HumanoidRootPart")
    
    if root and giantRoot then
        giantRoot.CFrame = root.CFrame * CFrame.new(0, 0, -20) * CFrame.Angles(0, math.pi, 0)
    end
    
    for _, part in pairs(giant:GetDescendants()) do
        if part:IsA("BasePart") then
            part.Material = Enum.Material.Neon
            part.Color = Color3.fromHSV(math.random(), 1, 1)
        end
    end
    
    giant.Parent = workspace
    
    local danceAnim = Instance.new("Animation")
    danceAnim.AnimationId = "rbxassetid://507771019"
    local danceTrack = humanoid:LoadAnimation(danceAnim)
    danceTrack:Play()
    
    local sound = Instance.new("Sound")
    sound.SoundId = "rbxassetid://1838618353"
    sound.Volume = 10
    sound.Looped = true
    
    local head = giant:FindFirstChild("Head")
    if head then
        sound.Parent = head
    else
        sound.Parent = giantRoot
    end
    sound:Play()
    
    local billboard = Instance.new("BillboardGui")
    billboard.Size = UDim2.new(0, 300, 0, 80)
    billboard.StudsOffset = Vector3.new(0, 8, 0)
    billboard.AlwaysOnTop = true
    
    local text = Instance.new("TextLabel")
    text.Size = UDim2.new(1, 0, 1, 0)
    text.BackgroundTransparency = 1
    text.Text = "🎉 SAKUGA EVENT! 🎉\nGIANT DANCE PARTY"
    text.TextColor3 = Color3.fromRGB(255, 255, 0)
    text.TextStrokeTransparency = 0
    text.TextStrokeColor3 = Color3.fromRGB(255, 0, 255)
    text.TextScaled = true
    text.Font = Enum.Font.GothamBlack
    text.Parent = billboard
    
    if head then
        billboard.Parent = head
    else
        billboard.Parent = giantRoot
    end
    
    local colorConn = RunService.Heartbeat:Connect(function()
        if giant and giant.Parent then
            local hue = (tick() * 2) % 1
            for _, part in pairs(giant:GetDescendants()) do
                if part:IsA("BasePart") then
                    part.Color = Color3.fromHSV(hue, 1, 1)
                end
            end
        end
    end)
    
    task.delay(30, function()
        if eventData and eventData.model == giant then
            if giant then giant:Destroy() end
            if sound then sound:Destroy() end
            colorConn:Disconnect()
            eventData = nil
        end
    end)
    
    eventData = {
        model = giant,
        sound = sound,
        connection = colorConn
    }
    
    notify("EVENT STARTED!", "Giant dancing clone spawned! (CLIENT ONLY)", 5)
    return "🎉 EVENT STARTED! Giant dancing sakuga with music! (Only you see this)"
end

-- ==================== TORNADO SYSTEM ====================
local function tornadoPlayer(targetName)
    if tornadoConnection then return "The wind is already screaming." end
    
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    tornadoTarget = target
    local startTime = tick()
    
    tornadoConnection = RunService.Heartbeat:Connect(function()
        local char = tornadoTarget and tornadoTarget.Character
        if not tornadoTarget or not tornadoTarget.Parent or not char then
            tornadoConnection:Disconnect()
            tornadoConnection = nil
            tornadoTarget = nil
            return
        end
        
        local root = char:FindFirstChild("HumanoidRootPart")
        local humanoid = char:FindFirstChildOfClass("Humanoid")
        if not root or not humanoid then return end
        
        local elapsed = tick() - startTime
        
        if elapsed > 5 then
            tornadoConnection:Disconnect()
            tornadoConnection = nil
            tornadoTarget = nil
            humanoid.PlatformStand = false
            return
        end
        
        humanoid.PlatformStand = true
        root.CFrame = root.CFrame * CFrame.Angles(0, 0.45, 0) + Vector3.new(0, 0.35, 0)
    end)
    
    task.spawn(function()
        local char = target.Character
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        
        local debris = {}
        for i = 1, 12 do
            local part = Instance.new("Part")
            part.Size = Vector3.new(math.random(1,3), math.random(1,3), math.random(1,3))
            part.Color = Color3.fromHSV(math.random(), 1, 1)
            part.Material = Enum.Material.Neon
            part.CanCollide = false
            part.Anchored = true
            part.Parent = workspace
            table.insert(debris, {part = part, angle = (i/12) * math.pi * 2, dist = 4, height = math.random(-2, 5)})
        end
        
        while tornadoConnection and tornadoTarget == target and target.Parent do
            local t = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
            if not t then break end
            for _, d in pairs(debris) do
                d.angle = d.angle + 0.25
                d.height = d.height + 0.1
                if d.height > 8 then d.height = -3 end
                local pos = t.Position + Vector3.new(math.cos(d.angle) * d.dist, d.height, math.sin(d.angle) * d.dist)
                d.part.CFrame = CFrame.new(pos) * CFrame.Angles(d.angle, d.angle, 0)
            end
            task.wait(0.03)
        end
        for _, d in pairs(debris) do d.part:Destroy() end
    end)
    
    return "🌪️ " .. target.Name .. " has been turned into a TORNADO! Spinning for 5 seconds!"
end

-- ==================== FLIP SYSTEM ====================
local function flipPlayer(targetName, flipType)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    local theirChar = target.Character
    if not theirChar then return "No body to claim..." end
    
    local root = theirChar:FindFirstChild("HumanoidRootPart")
    local humanoid = theirChar:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid then return "The bones are missing." end
    
    task.spawn(function()
        local startCF = root.CFrame
        local startPos = root.Position
        local duration = 0.7
        local t = 0
        local flipDir = (flipType == "front") and 1 or -1
        
        while t < duration do
            t = t + task.wait()
            local alpha = math.min(t / duration, 1)
            local angle = flipDir * math.pi * 2 * alpha
            root.CFrame = CFrame.new(startPos) * (startCF - startCF.Position) * CFrame.Angles(angle, 0, 0)
        end
        root.CFrame = CFrame.new(startPos) * (startCF - startCF.Position)
    end)
    
    if flipType == "front" then
        return "🤸 " .. target.Name .. " did a FRONT FLIP!"
    else
        return "🤸 " .. target.Name .. " did a BACKFLIP!"
    end
end

-- ==================== CROSS SYSTEM ====================
local function crossPlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    if crossData and crossData.target == target then
        if crossData.model then crossData.model:Destroy() end
        if crossData.connection then crossData.connection:Disconnect() end
        crossData = nil
        return "The nails are pulled from " .. target.Name .. "."
    end
    
    local theirChar = target.Character
    if not theirChar then return "No body to claim..." end
    
    local theirRoot = theirChar:FindFirstChild("HumanoidRootPart")
    if not theirRoot then return "Nothing anchors them here." end
    
    local crossModel = Instance.new("Model")
    crossModel.Name = "CrossOf" .. target.Name
    
    local vertical = Instance.new("Part")
    vertical.Name = "Vertical"
    vertical.Size = Vector3.new(2, 14, 2)
    vertical.Material = Enum.Material.Wood
    vertical.Color = Color3.fromRGB(101, 67, 33)
    vertical.Anchored = true
    vertical.Parent = crossModel
    
    local horizontal = Instance.new("Part")
    horizontal.Name = "Horizontal"
    horizontal.Size = Vector3.new(10, 2, 2)
    horizontal.Material = Enum.Material.Wood
    horizontal.Color = Color3.fromRGB(101, 67, 33)
    horizontal.Anchored = true
    horizontal.Parent = crossModel
    
    local crossPos = theirRoot.Position + (theirRoot.CFrame.LookVector * -3)
    vertical.CFrame = CFrame.new(crossPos) * CFrame.Angles(0, math.random() * math.pi, 0.1)
    horizontal.CFrame = vertical.CFrame * CFrame.new(0, 2, 0)
    
    local fire = Instance.new("Fire")
    fire.Size = 15
    fire.Heat = 25
    fire.Color = Color3.fromRGB(255, 100, 0)
    fire.SecondaryColor = Color3.fromRGB(255, 0, 0)
    fire.Parent = vertical
    
    local fire2 = fire:Clone()
    fire2.Parent = horizontal
    
    local smoke = Instance.new("Smoke")
    smoke.Size = 10
    smoke.Opacity = 0.5
    smoke.Color = Color3.fromRGB(100, 100, 100)
    smoke.Parent = vertical
    
    crossModel.Parent = workspace
    
    local humanoid = theirChar:FindFirstChildOfClass("Humanoid")
    if humanoid then
        humanoid.PlatformStand = true
    end
    
    local weld = Instance.new("Weld")
    weld.Part0 = theirRoot
    weld.Part1 = vertical
    weld.C0 = CFrame.new(0, 0, 1.5)
    weld.Parent = theirRoot
    
    local conn = RunService.Heartbeat:Connect(function()
        if not target.Parent or not target.Character then
            if crossData and crossData.model then
                crossData.model:Destroy()
            end
            crossData = nil
            return
        end
        local root = target.Character:FindFirstChild("HumanoidRootPart")
        local hum = target.Character:FindFirstChildOfClass("Humanoid")
        if root and hum then
            hum.PlatformStand = true
            hum.Health = hum.Health - 0.1
        end
    end)
    
    crossData = {
        target = target,
        model = crossModel,
        connection = conn,
        weld = weld
    }
    
    task.delay(10, function()
        if crossData and crossData.target == target then
            if crossData.model then crossData.model:Destroy() end
            if crossData.connection then crossData.connection:Disconnect() end
            crossData = nil
        end
    end)
    
    return "Nailed " .. target.Name .. " to the wood. They will hang."
end

-- ==================== CAGE SYSTEM ====================
local function cagePlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    local theirChar = target.Character
    if not theirChar then return "No body to claim..." end
    
    local theirRoot = theirChar:FindFirstChild("HumanoidRootPart")
    if not theirRoot then return "Nothing anchors them here." end
    
    local cage = Instance.new("Model")
    cage.Name = "Cage"
    
    for i = 1, 8 do
        local bar = Instance.new("Part")
        bar.Size = Vector3.new(0.5, 12, 0.5)
        bar.Material = Enum.Material.Metal
        bar.Color = Color3.fromRGB(80, 80, 80)
        bar.Anchored = true
        
        local angle = (i / 8) * math.pi * 2
        local pos = theirRoot.Position + Vector3.new(math.cos(angle) * 4, 4, math.sin(angle) * 4)
        bar.CFrame = CFrame.new(pos) * CFrame.Angles(0, angle, 0)
        bar.Parent = cage
    end
    
    for _, y in pairs({0, 8}) do
        local ring = Instance.new("Part")
        ring.Size = Vector3.new(8, 0.5, 8)
        ring.Material = Enum.Material.Metal
        ring.Color = Color3.fromRGB(80, 80, 80)
        ring.Anchored = true
        ring.CFrame = CFrame.new(theirRoot.Position + Vector3.new(0, y, 0))
        ring.Parent = cage
    end
    
    cage.Parent = workspace
    
    task.delay(8, function()
        if cage and cage.Parent then
            cage:Destroy()
        end
    end)
    
    return "Locked " .. target.Name .. " behind the bars. No escape."
end


-- ==================== SPIN SYSTEM ====================
local function spinPlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    if spinConnections[target] then
        spinConnections[target]:Disconnect()
        spinConnections[target] = nil
        return "The spinning stops. For now."
    end
    
    local theirChar = target.Character
    if not theirChar then return "No body to claim..." end
    
    local conn = RunService.Heartbeat:Connect(function()
        if not target.Parent or not target.Character then
            spinConnections[target] = nil
            return
        end
        local root = target.Character:FindFirstChild("HumanoidRootPart")
        if root then
            root.CFrame = root.CFrame * CFrame.Angles(0, 0.5, 0)
        end
    end)
    
    spinConnections[target] = conn
    return "Making " .. target.Name .. " spin until the world blurs."
end

