-- ==================== RAGDOLL SYSTEM ====================
local function ragdollPlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    local theirChar = target.Character
    if not theirChar then return "No body to claim..." end
    
    local humanoid = theirChar:FindFirstChildOfClass("Humanoid")
    if humanoid then
        humanoid.PlatformStand = true
        humanoid.AutoRotate = false
        
        for _, part in pairs(theirChar:GetDescendants()) do
            if part:IsA("Motor6D") then
                local socket = Instance.new("BallSocketConstraint")
                socket.Part0 = part.Part0
                socket.Part1 = part.Part1
                socket.Parent = part.Part0
                part:Destroy()
            end
        end
        
        task.delay(5, function()
            if target.Character then
                local hum = target.Character:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.PlatformStand = false
                    hum.AutoRotate = true
                end
            end
        end)
    end
    
    return "Bones go soft. " .. target.Name .. " collapses."
end

-- ==================== RAINBOW SYSTEM ====================
local function rainbowPlayer(targetName)
    if targetName:lower() == "me" then targetName = LocalPlayer.Name end
    
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    if rainbowConnections[target] then
        rainbowConnections[target]:Disconnect()
        rainbowConnections[target] = nil
        return "The colors drain away."
    end
    
    local hue = 0
    local conn = RunService.Heartbeat:Connect(function()
        if not target.Parent then return end
        if target.Character then
            hue = (hue + 0.02) % 1
            local color = Color3.fromHSV(hue, 1, 1)
            for _, part in pairs(target.Character:GetDescendants()) do
                if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                    part.Color = color
                end
            end
        end
    end)
    
    rainbowConnections[target] = conn
    return "Colors crawl over " .. target.Name .. "."
end

-- ==================== ORBIT SYSTEM ====================
local function orbitPlayer(targetName, orbitTargetName)
    local target = findPlayer(targetName)
    local center = findPlayer(orbitTargetName)
    
    if not target or not center then return "That name is not known to Cyris." end
    
    local key = target.Name .. "_" .. center.Name
    if orbitConnections[key] then
        orbitConnections[key]:Disconnect()
        orbitConnections[key] = nil
        return "The orbit breaks."
    end
    
    local angle = 0
    local conn = RunService.Heartbeat:Connect(function()
        if not target.Parent or not center.Parent then
            orbitConnections[key] = nil
            return
        end
        
        local tChar = target.Character
        local cChar = center.Character
        if not tChar or not cChar then return end
        
        local tRoot = tChar:FindFirstChild("HumanoidRootPart")
        local cRoot = cChar:FindFirstChild("HumanoidRootPart")
        if not tRoot or not cRoot then return end
        
        angle = angle + 0.05
        local radius = 8
        local offset = Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius)
        tRoot.CFrame = CFrame.new(cRoot.Position + offset)
    end)
    
    orbitConnections[key] = conn
    return target.Name .. " orbiting " .. center.Name .. "!"
end

-- ==================== CAR SYSTEM ====================
local function carPlayer(targetName)
    if sitConnection then 
        sitConnection:Disconnect()
        sitConnection = nil
    end
    
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    if target == LocalPlayer then return "You cannot mount your own flesh." end
    
    sittingOn = target
    sitMode = "car"
    
    local character = LocalPlayer.Character
    if not character then return "No body to claim..." end
    
    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid then return "The vessel is not ready." end
    
    humanoid.PlatformStand = true
    
    sitConnection = RunService.Heartbeat:Connect(function()
        if not sittingOn or not sittingOn.Parent then
            if sitConnection then
                sitConnection:Disconnect()
                sitConnection = nil
            end
            humanoid.PlatformStand = false
            return
        end
        
        local targetChar = sittingOn.Character
        if not targetChar then return end
        
        local targetHead = targetChar:FindFirstChild("Head")
        local targetRoot = targetChar:FindFirstChild("HumanoidRootPart")
        if not targetHead or not targetRoot then return end
        
        local shoulderPos = targetHead.Position + Vector3.new(0, targetHead.Size.Y/2 + 2, 0)
        root.CFrame = CFrame.new(shoulderPos) * CFrame.Angles(0, math.rad(targetRoot.Orientation.Y), 0)
    end)
    
    return "Riding " .. target.Name .. " like a car! 🚗"
end

