-- ==================== TRAIL SYSTEM ====================
local function toggleTrail()
    local character = LocalPlayer.Character
    if not character then return "No body to claim..." end
    
    local hasTrail = character:GetAttribute("HasTrail")
    
    if hasTrail then
        for _, part in pairs(character:GetDescendants()) do
            if part:IsA("Trail") then
                part:Destroy()
            end
        end
        character:SetAttribute("HasTrail", false)
        return "The trail fades."
    else
        for _, part in pairs(character:GetDescendants()) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                local trail = Instance.new("Trail")
                trail.Color = ColorSequence.new(Color3.fromRGB(255, 0, 0), Color3.fromRGB(0, 0, 255))
                trail.Lifetime = 1
                trail.Parent = part
            end
        end
        character:SetAttribute("HasTrail", true)
        return "You leave a trail of something dark."
    end
end

