-- ==================== ENHANCED JUMPSCARE ====================
local function jumpscarePlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    if target == LocalPlayer then return "Can't jumpscare yourself." end
    
    local theirChar = target.Character
    if not theirChar then return "No body to claim..." end
    
    local theirHead = theirChar:FindFirstChild("Head")
    if not theirHead then return "Head not found." end
    
    local jumpscareGui = Instance.new("ScreenGui")
    jumpscareGui.Name = "JUMPSCARE"
    jumpscareGui.IgnoreGuiInset = true
    
    local bg = Instance.new("Frame")
    bg.Size = UDim2.new(1, 0, 1, 0)
    bg.BackgroundColor3 = Color3.new(0, 0, 0)
    bg.BorderSizePixel = 0
    bg.Parent = jumpscareGui
    
    local face1 = Instance.new("ImageLabel")
    face1.Size = UDim2.new(0.8, 0, 0.8, 0)
    face1.Position = UDim2.new(0.1, 0, 0.1, 0)
    face1.BackgroundTransparency = 1
    face1.Image = "rbxassetid://1119700310"
    face1.ImageColor3 = Color3.fromRGB(255, 0, 0)
    face1.Parent = jumpscareGui
    
    local face2 = Instance.new("ImageLabel")
    face2.Size = UDim2.new(0.8, 0, 0.8, 0)
    face2.Position = UDim2.new(0.12, 0, 0.12, 0)
    face2.BackgroundTransparency = 1
    face2.Image = "rbxassetid://1119700310"
    face2.ImageColor3 = Color3.fromRGB(0, 255, 255)
    face2.ImageTransparency = 0.5
    face2.Parent = jumpscareGui
    
    local text = Instance.new("TextLabel")
    text.Size = UDim2.new(1, 0, 0.2, 0)
    text.Position = UDim2.new(0, 0, 0.8, 0)
    text.BackgroundTransparency = 1
    text.Text = "LOOK BEHIND YOU"
    text.TextColor3 = Color3.fromRGB(255, 0, 0)
    text.TextScaled = true
    text.Font = Enum.Font.GothamBlack
    text.Parent = jumpscareGui
    
    pcall(function()
        local playerGui = target:FindFirstChild("PlayerGui")
        if playerGui then
            jumpscareGui.Parent = playerGui
            
            local camera = workspace.CurrentCamera
            local originalCFrame = camera.CFrame
            
            task.spawn(function()
                for i = 1, 30 do
                    camera.CFrame = originalCFrame * CFrame.new(
                        math.random(-5, 5),
                        math.random(-5, 5),
                        math.random(-5, 5)
                    ) * CFrame.Angles(
                        math.random(-0.5, 0.5),
                        math.random(-0.5, 0.5),
                        math.random(-0.5, 0.5)
                    )
                    task.wait(0.03)
                end
                camera.CFrame = originalCFrame
            end)
            
            for i = 1, 20 do
                bg.BackgroundColor3 = Color3.fromRGB(255, 0, 0)
                face1.ImageColor3 = Color3.new(1, 1, 1)
                face2.ImageColor3 = Color3.fromRGB(255, 0, 0)
                text.TextColor3 = Color3.new(0, 0, 0)
                task.wait(0.05)
                
                bg.BackgroundColor3 = Color3.new(0, 0, 0)
                face1.ImageColor3 = Color3.fromRGB(255, 0, 0)
                face2.ImageColor3 = Color3.fromRGB(0, 255, 255)
                text.TextColor3 = Color3.fromRGB(255, 0, 0)
                task.wait(0.05)
                
                bg.BackgroundColor3 = Color3.new(1, 1, 1)
                face1.ImageColor3 = Color3.new(0, 0, 0)
                text.TextColor3 = Color3.new(0, 0, 0)
                task.wait(0.03)
            end
            
            task.delay(0.1, function()
                if jumpscareGui and jumpscareGui.Parent then
                    jumpscareGui:Destroy()
                end
            end)
        end
    end)
    
    for _, part in pairs(theirChar:GetDescendants()) do
        if part:IsA("BasePart") then
            local originalColor = part.Color
            part.Color = Color3.fromRGB(255, 0, 0)
            task.delay(1, function()
                if part and part.Parent then
                    part.Color = originalColor
                end
            end)
        end
    end
    
    local oldAmbient = Lighting.Ambient
    local oldBrightness = Lighting.Brightness
    local oldColorShift = Lighting.ColorShift_Top
    
    task.spawn(function()
        for i = 1, 10 do
            Lighting.Ambient = Color3.fromRGB(255, 0, 0)
            Lighting.Brightness = 10
            Lighting.ColorShift_Top = Color3.fromRGB(255, 0, 0)
