        sound:Play()
        task.delay(2, function()
            if sound then sound:Destroy() end
        end)
    end)
    
    return "Jumpscared " .. target.Name .. "!"
end

-- ==================== CRACK SYSTEM ====================
local function crackPlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    if target == LocalPlayer then return "Can't crack yourself." end
    
    if crackConnection then
        crackConnection:Disconnect()
        crackConnection = nil
        crackTargetPlayer = nil
    end
    
    crackTargetPlayer = target
    
    local theirChar = target.Character
    if not theirChar then return "Target character not found." end
    
    local theirRoot = theirChar:FindFirstChild("HumanoidRootPart")
    if not theirRoot then return "Target root not found." end
    
    local myChar = LocalPlayer.Character
    if not myChar then return "Your character not found." end
    
    local myRoot = myChar:FindFirstChild("HumanoidRootPart")
    local myHumanoid = myChar:FindFirstChildOfClass("Humanoid")
    if not myRoot or not myHumanoid then return "Your parts not found." end
    
    local bodyPos = Instance.new("BodyPosition")
    bodyPos.MaxForce = Vector3.new(10000, 10000, 10000)
    bodyPos.P = 15000
    bodyPos.D = 1000
    bodyPos.Parent = myRoot
    
    local bodyGyro = Instance.new("BodyGyro")
    bodyGyro.MaxTorque = Vector3.new(10000, 10000, 10000)
    bodyGyro.P = 10000
    bodyGyro.Parent = myRoot
    
    myHumanoid.PlatformStand = true
    
    local startTime = tick()
    
    crackConnection = RunService.Heartbeat:Connect(function()
        if not crackTargetPlayer or not crackTargetPlayer.Parent then
            crackConnection:Disconnect()
            crackConnection = nil
            crackTargetPlayer = nil
            bodyPos:Destroy()
            bodyGyro:Destroy()
            myHumanoid.PlatformStand = false
            return
        end
        
        local currentTargetChar = crackTargetPlayer.Character
        if not currentTargetChar then
            crackConnection:Disconnect()
            crackConnection = nil
            crackTargetPlayer = nil
            bodyPos:Destroy()
            bodyGyro:Destroy()
            myHumanoid.PlatformStand = false
            return
        end
        
        local currentTargetRoot = currentTargetChar:FindFirstChild("HumanoidRootPart")
        if not currentTargetRoot then
            crackConnection:Disconnect()
            crackConnection = nil
            crackTargetPlayer = nil
            bodyPos:Destroy()
            bodyGyro:Destroy()
            myHumanoid.PlatformStand = false
            return
        end
        
        local elapsed = tick() - startTime
        if elapsed > 3 then
            crackConnection:Disconnect()
            crackConnection = nil
            crackTargetPlayer = nil
            bodyPos:Destroy()
            bodyGyro:Destroy()
            myHumanoid.PlatformStand = false
            sendChat("Crack finished.")
            return
        end
        
        local behindOffset = -currentTargetRoot.CFrame.LookVector * 3
        local targetPos = currentTargetRoot.Position + behindOffset + Vector3.new(0, 0, 0)
        
        local shakeOffset = math.sin(elapsed * 30) * 2
        local rightVector = currentTargetRoot.CFrame.RightVector
        local shakePos = targetPos + (rightVector * shakeOffset)
        
        bodyPos.Position = shakePos
        bodyGyro.CFrame = CFrame.lookAt(myRoot.Position, currentTargetRoot.Position)
    end)
    
    return "Cracking on " .. target.Name .. " for 3 seconds... (sticking behind them)"
end


