-- ==================== FREEZE SYSTEM ====================
local function freezePlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    if frozenPlayers[target] then
        if frozenPlayers[target].conn then
            frozenPlayers[target].conn:Disconnect()
        end
        if frozenPlayers[target].anchor then
            frozenPlayers[target].anchor:Destroy()
        end
        frozenPlayers[target] = nil
        return "Unfroze " .. target.Name .. "."
    end
    
    local theirChar = target.Character
    if not theirChar then return "No body to claim..." end
    
    local theirRoot = theirChar:FindFirstChild("HumanoidRootPart")
    if not theirRoot then return "Nothing anchors them here." end
    
    local anchor = Instance.new("BodyPosition")
    anchor.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
    anchor.P = 100000
    anchor.Position = theirRoot.Position
    anchor.Parent = theirRoot
    
    local conn = RunService.Heartbeat:Connect(function()
        if target.Character and target.Character:FindFirstChild("HumanoidRootPart") then
            anchor.Position = theirRoot.Position
        end
    end)
    
    frozenPlayers[target] = {conn = conn, anchor = anchor}
    return "Froze " .. target.Name .. ". Say it again to unfreeze."
end

-- ==================== LOOP BRING ====================
local function loopBring(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    
    if loopBringTargets[target] then
        loopBringTargets[target]:Disconnect()
        loopBringTargets[target] = nil
        return "Stopped loop bringing " .. target.Name .. "."
    end
    
    local conn = RunService.Heartbeat:Connect(function()
        if not target.Parent then
            loopBringTargets[target] = nil
            return
        end
        local theirChar = target.Character
        local myChar = LocalPlayer.Character
        if theirChar and myChar then
            local theirRoot = theirChar:FindFirstChild("HumanoidRootPart")
            local myRoot = myChar:FindFirstChild("HumanoidRootPart")
            if theirRoot and myRoot then
                theirRoot.CFrame = myRoot.CFrame + Vector3.new(0, 3, 0)
            end
        end
    end)
    
    loopBringTargets[target] = conn
    return "Loop bringing " .. target.Name .. ". Say it again to stop."
end

-- ==================== ESP SYSTEM ====================
local function toggleESP()
    if espEnabled then
        for _, highlight in pairs(espHighlights) do
            if highlight then highlight:Destroy() end
        end
        espHighlights = {}
        espEnabled = false
        return "ESP disabled."
    else
        espEnabled = true
        
        local function addESP(player)
            if player == LocalPlayer then return end
            local function onChar(char)
                local highlight = Instance.new("Highlight")
                highlight.Name = "ESPHighlight"
                highlight.FillColor = Color3.fromRGB(255, 0, 0)
                highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
                highlight.FillTransparency = 0.5
                highlight.OutlineTransparency = 0
                highlight.Adornee = char
                highlight.Parent = char
                espHighlights[player] = highlight
            end
            
            if player.Character then
                onChar(player.Character)
            end
            player.CharacterAdded:Connect(onChar)
        end
        
        for _, player in pairs(Players:GetPlayers()) do
            addESP(player)
        end
        
        Players.PlayerAdded:Connect(addESP)
        return "ESP enabled."
    end
end

