-- Refresh avatar / outfit WITHOUT dying (for changing fits)
local function refreshFit()
    local character = LocalPlayer.Character
    if not character then return "No character." end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local hrp = character:FindFirstChild("HumanoidRootPart")
    if not humanoid then return "No humanoid." end
    local savedCF = hrp and hrp.CFrame
    local ok, err = pcall(function()
        if hrp then hrp.Anchored = true end
        -- Prefer current website avatar description
        local desc = nil
        pcall(function()
            desc = Players:GetHumanoidDescriptionFromUserId(LocalPlayer.UserId)
        end)
        if not desc then
            pcall(function()
                desc = humanoid:GetAppliedDescription()
            end)
        end
        if desc then
            -- strip old clothes/accessories so they don't stack
            for _, child in ipairs(character:GetChildren()) do
                if child:IsA("Accessory") or child:IsA("Shirt") or child:IsA("Pants")
                    or child:IsA("ShirtGraphic") or child:IsA("BodyColors")
                    or child:IsA("CharacterMesh") then
                    pcall(function() child:Destroy() end)
                end
            end
            humanoid:ApplyDescription(desc)
        else
            -- last resort: force appearance reload
            pcall(function()
                LocalPlayer:ClearCharacterAppearance()
                LocalPlayer:LoadCharacterAppearance(LocalPlayer.CharacterAppearanceId)
            end)
        end
        task.wait(0.15)
        if hrp and hrp.Parent then
            if savedCF then hrp.CFrame = savedCF end
            hrp.Anchored = false
        end
    end)
    if not ok then
        if hrp then pcall(function() hrp.Anchored = false end) end
        return "Fit refresh failed: " .. tostring(err):sub(1, 60)
    end
    return "Fit refreshed — no reset. Outfit reloaded."
end

