-- ==================== BACKPACK SYSTEM ====================
local function backpackPlayer(targetName)
    if sitConnection then stopSitting() end
    
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    if target == LocalPlayer then return "Can't sit on yourself." end
    
    sittingOn = target
    sitMode = "backpack"
    
    local character = LocalPlayer.Character
    if not character then return "No body to claim..." end
    
    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid then return "The vessel is not ready." end
    
    local bodyPos = Instance.new("BodyPosition")
    bodyPos.Name = "BackpackPos"
    bodyPos.MaxForce = Vector3.new(5000, 5000, 5000)
    bodyPos.P = 10000
    bodyPos.D = 500
    bodyPos.Parent = root
    
    local bodyGyro = Instance.new("BodyGyro")
    bodyGyro.Name = "BackpackGyro"
    bodyGyro.MaxTorque = Vector3.new(5000, 5000, 5000)
    bodyGyro.P = 5000
    bodyGyro.Parent = root
    
    humanoid.PlatformStand = true
    
    sitConnection = RunService.Heartbeat:Connect(function()
        if not sittingOn or not sittingOn.Parent then
            stopSitting()
            return
        end
        
        local targetChar = sittingOn.Character
        if not targetChar then
            stopSitting()
            return
        end
        
        local targetRoot = targetChar:FindFirstChild("HumanoidRootPart")
        if not targetRoot then
            stopSitting()
            return
        end
        
        local backOffset = -targetRoot.CFrame.LookVector * 2.5
        local upOffset = Vector3.new(0, 1.5, 0)
        local targetPos = targetRoot.Position + backOffset + upOffset
        
        bodyPos.Position = targetPos
        bodyGyro.CFrame = targetRoot.CFrame
    end)
    
    return "Sitting on " .. target.Name .. "'s back. Say 'cyris stop sitting' to get off."
end

-- ==================== HEADSIT SYSTEM ====================
local function headsitPlayer(targetName)
    if sitConnection then stopSitting() end
    
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    if target == LocalPlayer then return "Can't sit on yourself." end
    
    sittingOn = target
    sitMode = "headsit"
    
    local character = LocalPlayer.Character
    if not character then return "No body to claim..." end
    
    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid then return "The vessel is not ready." end
    
    local bodyPos = Instance.new("BodyPosition")
    bodyPos.Name = "HeadsitPos"
    bodyPos.MaxForce = Vector3.new(5000, 5000, 5000)
    bodyPos.P = 10000
    bodyPos.D = 500
    bodyPos.Parent = root
    
    local bodyGyro = Instance.new("BodyGyro")
    bodyGyro.Name = "HeadsitGyro"
    bodyGyro.MaxTorque = Vector3.new(5000, 5000, 5000)
    bodyGyro.P = 5000
    bodyGyro.Parent = root
    
    humanoid.PlatformStand = true
    
    sitConnection = RunService.Heartbeat:Connect(function()
        if not sittingOn or not sittingOn.Parent then
            stopSitting()
            return
        end
        
        local targetChar = sittingOn.Character
        if not targetChar then
            stopSitting()
            return
        end
        
