        end
        
        local headTop = targetHead.Position + Vector3.new(0, targetHead.Size.Y/2 + 1, 0)
        
        bodyPos.Position = headTop
        bodyGyro.CFrame = targetRoot.CFrame
    end)
    
    return "Sitting on " .. target.Name .. "'s head. Say 'cyris stop sitting' to get off."
end

-- ==================== ATTACH SYSTEM ====================
local function stopAttaching()
    if attachConnection then
        attachConnection:Disconnect()
        attachConnection = nil
    end
    attachedTo = nil
    local character = LocalPlayer.Character
    if character then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            humanoid.PlatformStand = false
        end
        local root = character:FindFirstChild("HumanoidRootPart")
        if root then
            for _, obj in pairs(root:GetChildren()) do
                if obj:IsA("BodyPosition") or obj:IsA("BodyGyro") then
                    obj:Destroy()
                end
            end
        end
    end
    return "Detached."
end

local function attachToPlayer(targetName)
    if attachConnection then stopAttaching() end
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    if target == LocalPlayer then return "Can't attach to yourself." end
    
    attachedTo = target
    local character = LocalPlayer.Character
    if not character then return "No body to claim..." end
    
    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid then return "The vessel is not ready." end
    
    local bodyPos = Instance.new("BodyPosition")
    bodyPos.MaxForce = Vector3.new(5000, 5000, 5000)
    bodyPos.P = 10000
    bodyPos.D = 500
    bodyPos.Parent = root
    
    local bodyGyro = Instance.new("BodyGyro")
    bodyGyro.MaxTorque = Vector3.new(5000, 5000, 5000)
    bodyGyro.P = 5000
    bodyGyro.Parent = root
    
    humanoid.PlatformStand = true
    
    attachConnection = RunService.Heartbeat:Connect(function()
        if not attachedTo or not attachedTo.Parent then
            stopAttaching()
            return
        end
        local targetChar = attachedTo.Character
        if not targetChar then
            stopAttaching()
            return
        end
        local targetHead = targetChar:FindFirstChild("Head")
        local targetRoot = targetChar:FindFirstChild("HumanoidRootPart")
        if targetHead and targetRoot then
            local targetPos = targetHead.Position + Vector3.new(0, targetHead.Size.Y/2 + 1, 0)
            bodyPos.Position = targetPos
            bodyGyro.CFrame = targetRoot.CFrame
        else
            stopAttaching()
        end
    end)
    
    return "Attached to " .. target.Name .. ". Say 'Cyris detach' to stop."
end

-- ==================== BRING SYSTEM ====================
local function stopBringing(targetPlayer)
    if bringConnections[targetPlayer] then
        bringConnections[targetPlayer]:Disconnect()
        bringConnections[targetPlayer] = nil
    end
end

local function bringPlayer(targetName)
    local target = findPlayer(targetName)
    if not target then return "That name is not known to Cyris." end
    if target == LocalPlayer then return "Can't bring yourself." end
    
    stopBringing(target)
    
    local myChar = LocalPlayer.Character
    local theirChar = target.Character
    if not myChar or not theirChar then return "No body to claim..." end
    
    local myRoot = myChar:FindFirstChild("HumanoidRootPart")
    local theirRoot = theirChar:FindFirstChild("HumanoidRootPart")
    if not myRoot or not theirRoot then return "Nothing anchors them here." end
    
    theirRoot.CFrame = myRoot.CFrame + Vector3.new(0, 3, 0)
    
    local bringConn = RunService.Heartbeat:Connect(function()
        if not target.Parent or not target.Character then
            stopBringing(target)
            return
        end
        local tRoot = target.Character:FindFirstChild("HumanoidRootPart")
        local mRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if tRoot and mRoot then
            local distance = (tRoot.Position - mRoot.Position).Magnitude
            if distance > 10 then
                tRoot.CFrame = mRoot.CFrame + Vector3.new(0, 3, 0)
            end
        end
    end)
    
    bringConnections[target] = bringConn
    task.delay(3, function() stopBringing(target) end)
    return "Brought " .. target.Name .. "."
end

-- ==================== CLONE SYSTEM ====================
local function removeClones()
    for _, cloneData in pairs(clones) do
        if cloneData.model and cloneData.model.Parent then
            cloneData.model:Destroy()
        end
    end
    clones = {}
    if cloneUpdateConnection then
        cloneUpdateConnection:Disconnect()
        cloneUpdateConnection = nil
    end
    return "All clones removed."
end

local function updateClones()
    local character = LocalPlayer.Character
    if not character then return end
    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then return end
    
    for i, cloneData in pairs(clones) do
        local clone = cloneData.model
        if clone and clone.Parent then
            local cloneRoot = clone:FindFirstChild("HumanoidRootPart")
            local cloneHumanoid = clone:FindFirstChildOfClass("Humanoid")
            local bodyPos = cloneData.bodyPos
            local bodyGyro = cloneData.bodyGyro
            if cloneRoot and cloneHumanoid and bodyPos and bodyGyro then
                local offset = cloneData.offset or Vector3.new(0, 0, 5)
                local targetPos = root.Position + (root.CFrame.LookVector * -5) + offset
                bodyPos.Position = targetPos
                bodyGyro.CFrame = CFrame.lookAt(cloneRoot.Position, root.Position)
                local velocity = root.Velocity
                if velocity.Magnitude > 1 then
                    cloneHumanoid.WalkSpeed = 16
                    cloneHumanoid:MoveTo(targetPos)
                else
                    cloneHumanoid.WalkSpeed = 0
                end
            end
        else
            table.remove(clones, i)
        end
    end
end

local function startCloneUpdate()
    if cloneUpdateConnection then return end
    cloneUpdateConnection = RunService.Heartbeat:Connect(updateClones)
end

local function cloneCharacter(amount)
    amount = math.min(tonumber(amount) or 1, 10)
    local created = 0
    local character = LocalPlayer.Character
    if not character then return "No body to claim..." end
    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then return "The vessel is not ready." end
    
    for i = 1, amount do
        task.wait(0.15)
        character = LocalPlayer.Character
        if not character then continue end
        local currentRoot = character:FindFirstChild("HumanoidRootPart")
        if not currentRoot then continue end
        
        local clone = character:Clone()
        if not clone then continue end
        
        clone.Name = LocalPlayer.Name .. "_Clone_" .. #clones + 1
        for _, obj in pairs(clone:GetDescendants()) do
            if obj:IsA("Script") or obj:IsA("LocalScript") or obj:IsA("BillboardGui") or obj:IsA("ScreenGui") then
                obj:Destroy()
            end
        end
        
        local cloneRoot = clone:FindFirstChild("HumanoidRootPart")
        local cloneHumanoid = clone:FindFirstChildOfClass("Humanoid")
        if not cloneRoot or not cloneHumanoid then
            clone:Destroy()
            continue
        end
        
        cloneHumanoid.DisplayName = LocalPlayer.DisplayName .. " (Clone)"
        cloneHumanoid.Health = cloneHumanoid.MaxHealth
        cloneHumanoid.PlatformStand = false
        cloneHumanoid.AutoRotate = false
        
        for _, part in pairs(clone:GetDescendants()) do
            if part:IsA("BasePart") then
                part.Transparency = math.min(part.Transparency + 0.25, 0.6)
                part.CanCollide = true
            end
        end
        
        local angle = (math.pi * 2 * #clones) / math.max(#clones + 1, 1)
        local offset = Vector3.new(math.cos(angle) * 5, 0, math.sin(angle) * 5)
        cloneRoot.CFrame = currentRoot.CFrame + offset
        
        local bodyPos = Instance.new("BodyPosition")
        bodyPos.MaxForce = Vector3.new(4000, 4000, 4000)
        bodyPos.P = 10000
        bodyPos.D = 500
        bodyPos.Position = cloneRoot.Position
        bodyPos.Parent = cloneRoot
        
        local bodyGyro = Instance.new("BodyGyro")
        bodyGyro.MaxTorque = Vector3.new(4000, 4000, 4000)
        bodyGyro.P = 5000
        bodyGyro.D = 100
        bodyGyro.CFrame = cloneRoot.CFrame
        bodyGyro.Parent = cloneRoot
        
        clone.Parent = workspace
        table.insert(clones, {model = clone, bodyPos = bodyPos, bodyGyro = bodyGyro, offset = offset, humanoid = cloneHumanoid})
        created = created + 1
        if #clones == 1 then startCloneUpdate() end
    end
    return "Created " .. created .. " clone" .. (created ~= 1 and "s" or "") .. "."
end

-- ==================== FLY SYSTEM ====================
 
local function startFlying() 
    if flying then return "I'm already flying." end
    local character = LocalPlayer.Character 
    if not character then return "No body to claim..." end
    local root = character:FindFirstChild("HumanoidRootPart") 
    local humanoid = character:FindFirstChildOfClass("Humanoid") 
    if not root or not humanoid then return "Character isn't ready." end
    
    flying = true 
    humanoid.PlatformStand = true 
    flyVelocity = Instance.new("BodyVelocity") 
    flyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge) 
    flyVelocity.Velocity = Vector3.zero 
    flyVelocity.Parent = root 
    flyGyro = Instance.new("BodyGyro") 
    flyGyro.MaxTorque = Vector3.new(math.huge, math.huge, math.huge) 
    flyGyro.P = 90000 
    flyGyro.CFrame = root.CFrame 
    flyGyro.Parent = root 
    
    flyConnection = RunService.RenderStepped:Connect(function() 
        if not flying or not root.Parent then return end
        local camera = workspace.CurrentCamera 
        local move = Vector3.zero 
        if UserInputService:IsKeyDown(Enum.KeyCode.W) then move += camera.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then move -= camera.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.A) then move -= camera.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.D) then move += camera.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then move += Vector3.new(0, 1, 0) end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then move -= Vector3.new(0, 1, 0) end
        if move.Magnitude > 0 then move = move.Unit * flySpeed end
        flyVelocity.Velocity = move 
        flyGyro.CFrame = camera.CFrame 
    end) 
    return "Flight enabled." 
end 
 
local function stopFlying() 
    if not flying then return "I'm not flying." end
    flying = false 
    if flyConnection then flyConnection:Disconnect() flyConnection = nil end
    if flyVelocity then flyVelocity:Destroy() flyVelocity = nil end
    if flyGyro then flyGyro:Destroy() flyGyro = nil end
    local character = LocalPlayer.Character 
    if character then
        local humanoid = character:FindFirstChildOfClass("Humanoid") 
        if humanoid then humanoid.PlatformStand = false end
    end
    return "Flight disabled." 
end 


