local function getReply(msg, speaker) 
    msg = string.lower(msg)
    local speakerName = string.lower(speaker.Name)
    
    -- RESTRICTED: Only "switches" can trigger this
    if msg:find("switches") and speakerName == "switches" then
        return "switches is the goat"
    end
    
    -- RESTRICTED: Only "immortal" can trigger this  
    if msg:find("immortal") and speakerName == "immortal" then
        return "immortal is so cool"
    end
    
    -- Help command
    if msg:find("help") or msg:find("commands") then
        return "Cyris listens... Commands: event, fly, noclip, god mode, freeze, cage, spin, blind, ragdoll, tornado, cross, light up, infinite baseplate, and many more. Speak carefully."
    end
    
    -- EVENT COMMAND
    if msg:find("event") and not msg:find("stop") then
        return createEvent()
    end
    
    -- Stop event
    if msg:find("stop event") or msg:find("end event") then
        if eventData then
            if eventData.model then eventData.model:Destroy() end
            if eventData.sound then eventData.sound:Destroy() end
            if eventData.connection then eventData.connection:Disconnect() end
            eventData = nil
            return "The celebration dies. The woods grow quiet again."
        end
        return "Nothing stirs... yet."
    end
    
    -- TORNADO COMMAND
    local tornadoMatch = msg:match("turn%s+([%w_]+)%s+into%s+a%s+tornado")
    if tornadoMatch then
        return tornadoPlayer(tornadoMatch)
    end
    local tornadoShort = msg:match("tornado%s+([%w_]+)")
    if tornadoShort and not tornadoMatch then
        return tornadoPlayer(tornadoShort)
    end
    if msg:find("tornado") and not tornadoMatch and not tornadoShort then
        return tornadoPlayer(LocalPlayer.Name)
    end
    
    -- FLIP COMMANDS
    local frontflipTarget = msg:match("front%s*flip%s+([%w_]+)")
    if frontflipTarget then
        return flipPlayer(frontflipTarget, "front")
    end
    local backflipTarget = msg:match("back%s*flip%s+([%w_]+)")
    if backflipTarget then
        return flipPlayer(backflipTarget, "back")
    end
    
    -- THE GAY QUESTION
    if msg:find("do you like boys") then
        return "YASSSSSSS 💅✨"
    end
    
    -- Cross command
    local crossTarget = msg:match("cross%s+([%w_]+)")
    if crossTarget then
        return crossPlayer(crossTarget)
    end
    
    -- Cage command
    local cageTarget = msg:match("cage%s+([%w_]+)")
