        return spinPlayer(spinTarget)
    end
    
    -- Blind command
    local blindTarget = msg:match("blind%s+([%w_]+)")
    if blindTarget then
        return blindPlayer(blindTarget)
    end
    
    -- Ragdoll command
    local ragdollTarget = msg:match("ragdoll%s+([%w_]+)")
    if ragdollTarget then
        return ragdollPlayer(ragdollTarget)
    end
    
    -- Rainbow command
    local rainbowTarget = msg:match("rainbow%s+([%w_]+)")
    if rainbowTarget then
        return rainbowPlayer(rainbowTarget)
    end
    
    -- Orbit command
    local orbitMatch = msg:match("orbit%s+([%w_]+)%s+around%s+([%w_]+)")
    if orbitMatch then
        local words = {}
        for word in msg:gmatch("%S+") do
            table.insert(words, word)
        end
        if #words >= 4 then
            return orbitPlayer(words[2], words[4])
        end
    end
    
    -- Car command
    local carTarget = msg:match("car%s+([%w_]+)") or msg:match("ride%s+([%w_]+)")
