    if danceTarget then
        return dancePlayer(danceTarget)
    end
    
    -- Shield toggle
    if msg:find("shield") then
        return toggleShield()
    end
    
    -- Trail toggle
    if msg:find("trail") then
        return toggleTrail()
    end
    
    -- Fun facts
    if msg:find("fact") or msg:find("tell me something") then
        return pick(funFacts)
    end
    
    -- Roasts
    if msg:find("roast") or msg:find("roast me") then
        return pick(roasts)
