        return pick(pickupLines)
    end
    
    -- Server sided message
    if msg:find("server sided tect") or msg:find("server message") then
        return serverMessage()
    end
    
    -- Jumpscare
    local jumpscareTarget = msg:match("jumpscare%s+([%w_]+)")
