        if (string.lower(crackTarget) == string.lower(LocalPlayer.Name) or string.lower(crackTarget) == string.lower(LocalPlayer.DisplayName)) and speaker ~= LocalPlayer then
            return crackPlayer(speaker.Name)
        elseif speaker == LocalPlayer then
            return crackPlayer(crackTarget)
        end
    end
 
    -- Fly
    if msg:find("make me fly") or msg:find("let me fly") or msg:find("start flying") then return startFlying() end
    if msg:find("stop flying") or msg:find("disable flying") or msg:find("make me stop flying") then return stopFlying() end
 
    -- Noclip
    if msg:find("noclip") then return toggleNoclip() end
    
    -- God mode
    if msg:find("god mode") or msg:find("godmode") then return toggleGodMode() end
    
    -- Speed
    local speed = msg:match("speed%s+(%d+)") or msg:match("set speed%s+(%d+)")
    if speed then return setSpeed(speed) end
    if msg:find("reset speed") then return setSpeed(defaultWalkSpeed) end
    
    -- Jump
    local jump = msg:match("jump%s+(%d+)") or msg:match("jump power%s+(%d+)")
    if jump then return setJump(jump) end
    if msg:find("reset jump") then return setJump(defaultJumpPower) end
    
    -- Invisible
    if msg:find("invisible") or msg:find("ghost mode") then return toggleInvisible() end
    
    -- Platform
    if msg:find("platform") or msg:find("spawn platform") then return createPlatform() end
    
    -- Fling
    local flingTarget = msg:match("fling%s+([%w_]+)") or msg:match("throw%s+([%w_]+)")
    if flingTarget then
        if speaker == LocalPlayer then
            return flingPlayer(flingTarget)
        elseif (string.lower(flingTarget) == string.lower(LocalPlayer.Name) or string.lower(flingTarget) == string.lower(LocalPlayer.DisplayName)) and speaker ~= LocalPlayer then
            return flingPlayer(LocalPlayer.Name, true)
        end
    end
    
    -- Freeze
    local freezeTarget = msg:match("freeze%s+([%w_]+)") or msg:match("stop%s+([%w_]+)")
    if freezeTarget and not msg:find("stop flying") then
        return freezePlayer(freezeTarget)
    end
    
    -- Loop bring
    local loopTarget = msg:match("loop%s+bring%s+([%w_]+)")
    if loopTarget then return loopBring(loopTarget) end
    
    -- Backpack
    local backpackTarget = msg:match("backpack%s+([%w_]+)") or msg:match("sit on back%s+([%w_]+)") or msg:match("ride%s+([%w_]+)")
    if backpackTarget then
        return backpackPlayer(backpackTarget)
    end
    
    -- Headsit
    local headsitTarget = msg:match("headsit%s+([%w_]+)") or msg:match("sit on head%s+([%w_]+)") or msg:match("head sit%s+([%w_]+)")
    if headsitTarget then
        return headsitPlayer(headsitTarget)
    end
    
    -- Stop sitting
    if msg:find("stop sitting") or msg:find("get off") or msg:find("hop off") then
        return stopSitting()
    end
    
    -- ESP
    if msg:find("esp") or msg:find("wallhack") or msg:find("see players") then return toggleESP() end
    
    -- Reset/Kill
    if msg:find("reset me") or msg:find("kill me") or msg:find("die") then return resetCharacter() end
    -- Refresh fit WITHOUT dying (reload avatar clothes/accessories)
    if msg:find("refresh fit") or msg:find("change fit") or msg:find("update fit") or msg:find("reload fit")
        or msg:find("refresh me") or msg == "refresh" or msg:find("cyris refresh") then
        return refreshFit()
    end
    
    -- Sit
    if msg:find("sit down") or (msg:find("sit") and not msg:find("headsit") and not msg:find("stop sitting")) then return sit() end
    
    -- Gravity
    local grav = msg:match("gravity%s+(%d+)") or msg:match("set gravity%s+(%d+)")
    if grav then return setGravity(grav) end
    if msg:find("reset gravity") then return setGravity(196.2) end
    if msg:find("low gravity") then return setGravity(50) end
    if msg:find("no gravity") or msg:find("zero gravity") then return setGravity(0) end
 
    -- Attach
    if msg:find("detach") or msg:find("unattach") then return stopAttaching() end
    local attachTarget = msg:match("attach%s+me%s+to%s+([%w_]+)") or msg:match("attach%s+to%s+([%w_]+)") or msg:match("stand%s+on%s+([%w_]+)")
    if attachTarget then return attachToPlayer(attachTarget) end
 
    -- Clone
    if msg:find("clone me") or msg:find("make a clone") or msg:find("create a clone") then return cloneCharacter(1) end
    local amount = msg:match("clone (%d+) times")
    if amount then return cloneCharacter(tonumber(amount)) end
    if msg:find("remove clones") then return removeClones() end
 
    -- Bring
    local bringTarget = msg:match("teleport%s+([%w_]+)%s+to%s+me") or msg:match("bring%s+([%w_]+)")
    if bringTarget then return bringPlayer(bringTarget) end
 
    -- Teleport to player
    local tpTarget = msg:match("teleport to%s+([%w_]+)") or msg:match("tp to%s+([%w_]+)")
    if tpTarget then
        local p = findPlayer(tpTarget)
        if p and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
            LocalPlayer.Character.HumanoidRootPart.CFrame = p.Character.HumanoidRootPart.CFrame + Vector3.new(0, 3, 0)
            return "Teleported to " .. p.Name
        end
        return "That name is not known to Cyris."
    end
 
    -- Math
    local a, op, b = msg:match("(%d+)%s*([%+%-%*/x])%s*(%d+)")
    if a and b then
        a, b = tonumber(a), tonumber(b)
        if op == "+" then return tostring(a + b)
        elseif op == "-" then return tostring(a - b)
        elseif op == "*" or op == "x" then return tostring(a * b)
        elseif op == "/" and b ~= 0 then return tostring(a / b) end
