-- ==================== HELPERS ====================
local function chat(msg)
	botSent[msg] = os.clock()
	pcall(function()
		local channels = TextChatService:FindFirstChild("TextChannels")
		local general = channels and channels:FindFirstChild("RBXGeneral")
		if general then
			general:SendAsync(msg)
		else
			LocalPlayer:Chat(msg)
		end
	end)
end

local function jchat(msg)
	chat("CYRIS: " .. msg)
end

local function findPlayer(name)
	if not name then return nil end
	name = string.lower(name)
	for _, p in pairs(Players:GetPlayers()) do
		if string.lower(p.Name) == name or string.lower(p.DisplayName) == name then
			return p
		end
	end
	return nil
end

local function getChar()
	return LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
end

local function getRoot()
	return getChar():FindFirstChild("HumanoidRootPart")
end

-- Per-command locks so a command can't overlap itself
local locks = {}
local function run(lockName, fn)
	task.spawn(function()
		if locks[lockName] then return end
		locks[lockName] = true
		local ok, err = pcall(fn)
		if not ok then warn("CYRIS error in " .. lockName .. ": " .. tostring(err)) end
		locks[lockName] = nil
	end)
end

-- Runs step(t) every frame for `duration` seconds, then onEnd(). Yields until done.
local function runFor(duration, step, onEnd)
	local start = os.clock()
	local done = false
	local conn
	conn = RunService.Heartbeat:Connect(function()
		local t = os.clock() - start
		if t >= duration then
			conn:Disconnect()
			if onEnd then pcall(onEnd) end
			done = true
			return
		end
		pcall(step, t)
	end)
	while not done do task.wait() end
end

-- ==================== BLACKLIST SYSTEM ====================
local BLACKLIST_FILE = "cyris_blacklist.json"
local blacklist = {} -- [lowercase name] = true

local function saveBlacklist()
	pcall(function()
		if writefile then
			local list = {}
			for name in pairs(blacklist) do table.insert(list, name) end
			writefile(BLACKLIST_FILE, HttpService:JSONEncode(list))
		end
	end)
end

local function loadBlacklist()
	pcall(function()
		if readfile and isfile and isfile(BLACKLIST_FILE) then
			for _, name in ipairs(HttpService:JSONDecode(readfile(BLACKLIST_FILE))) do
				blacklist[string.lower(name)] = true
			end
		end
	end)
end
loadBlacklist()

local function isBlacklisted(player)
	if not player or player == LocalPlayer then return false end
	return blacklist[string.lower(player.Name)] or blacklist[string.lower(player.DisplayName)] or false
end

local function blacklistUser(name)
	name = name:gsub("[\"']", "")
	local target = findPlayer(name)
	if target == LocalPlayer then
		return jchat("You can't blacklist yourself.")
	end
	local key = string.lower(target and target.Name or name)
	if blacklist[key] then
		return jchat(key .. " is already blacklisted.")
	end
	blacklist[key] = true
	saveBlacklist()
	jchat(key .. " has been blacklisted. They can no longer use Cyris.")
end

local function unblacklistUser(name)
	name = name:gsub("[\"']", "")
	local target = findPlayer(name)
	local removed = false
	for _, key in ipairs({ string.lower(name), target and string.lower(target.Name), target and string.lower(target.DisplayName) }) do
		if key and blacklist[key] then
			blacklist[key] = nil
			removed = true
		end
	end
	if removed then
		saveBlacklist()
		jchat(string.lower(target and target.Name or name) .. " has been removed from the blacklist.")
	else
		jchat(string.lower(name) .. " is not blacklisted.")
	end
end

local function listBlacklist()
	local names = {}
	for name in pairs(blacklist) do table.insert(names, name) end
	if #names == 0 then
		jchat("Blacklist is empty.")
	else
		jchat("Blacklisted: " .. table.concat(names, ", "))
	end
end

