-- TIME
local function tellTime()
	local t = os.date("*t")
	local hour, minute = t.hour, t.min
	local ampm = hour >= 12 and "PM" or "AM"
	if hour > 12 then hour = hour - 12 end
	if hour == 0 then hour = 12 end
	local stamp = hour .. ":" .. string.format("%02d", minute) .. " " .. ampm
	local responses = {
		"CYRIS: The current time is " .. stamp .. ".",
		"CYRIS: Time scan complete. It is " .. stamp .. ".",
		"CYRIS: My clock shows " .. stamp .. ".",
	}
	chat(responses[math.random(1, #responses)])
	task.wait(3)
end

