-- CRUCIFY ANIMATION (lay flat, slowly rise upright)
local function crucify()
	local char = getChar()
	local root = char:FindFirstChild("HumanoidRootPart")
	local hum = char:FindFirstChildOfClass("Humanoid")
	if not root or not hum then return end

	local oldAuto = hum.AutoRotate
	hum.AutoRotate = false
	root.Anchored = true

	local upright = root.CFrame
	local flat = upright * CFrame.Angles(math.rad(90), 0, 0)
	root.CFrame = flat
	task.wait(1)

	local tween = TweenService:Create(root, TweenInfo.new(4, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), { CFrame = upright })
	tween:Play()
	tween.Completed:Wait()

	root.Anchored = false
	hum.AutoRotate = oldAuto
end

-- SACRIFICE TIME (lay flat, rise into the air, hold, then come back down)
local function sacrificeTime()
	local char = getChar()
	local root = char:FindFirstChild("HumanoidRootPart")
	local hum = char:FindFirstChildOfClass("Humanoid")
	if not root or not hum then return end

	local oldAuto = hum.AutoRotate
	hum.AutoRotate = false
	root.Anchored = true -- keeps gravity from dragging you down mid-ritual

	local startCF = root.CFrame

	-- lay flat
	local flatCF = startCF * CFrame.Angles(math.rad(90), 0, 0)
	local flat = TweenService:Create(root, TweenInfo.new(1, Enum.EasingStyle.Sine), { CFrame = flatCF })
	flat:Play()
	flat.Completed:Wait()

	-- rise
	local liftCF = flatCF + Vector3.new(0, 50, 0)
	local lift = TweenService:Create(root, TweenInfo.new(8, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), { CFrame = liftCF })
	lift:Play()
	lift.Completed:Wait()

	task.wait(3) -- hover

	-- lower back down and stand up
	local lower = TweenService:Create(root, TweenInfo.new(4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), { CFrame = startCF })
	lower:Play()
	lower.Completed:Wait()

	root.Anchored = false
	hum.AutoRotate = oldAuto
	hum:ChangeState(Enum.HumanoidStateType.GettingUp)
end

