-- Returns TRUE if this block handled the message (so the old chat engine skips it).
-- Blacklisted speakers are swallowed here too, so they can't use ANY Cyris command.
aioHandle = function(speaker, text)
	if not speaker or type(text) ~= "string" then return false end

	local trimmed = text:gsub("^%s+", ""):gsub("%s+$", "")
	local lower = string.lower(trimmed)
	local isOwner = (speaker == LocalPlayer)

	-- Blacklist management: OWNER ONLY
	if isOwner then
		if lower == "cyris blacklist list" then
			listBlacklist()
			return true
		end
		local toBlock = lower:match("^cyris%s+blacklist%s+(.+)$")
		if toBlock then
			blacklistUser(toBlock)
			return true
		end
		local toUnblock = lower:match("^cyris%s+unblacklist%s+(.+)$")
		if toUnblock then
			unblacklistUser(toUnblock)
			return true
		end
	end

	-- Blacklisted users are ignored completely
	if isBlacklisted(speaker) then return true end

	-- cyris say <text>  (ignores text starting with "cyris" to avoid loops)
	if lower:sub(1, 10) == "cyris say" then
		local out = trimmed:sub(11):gsub("^%s+", "")
		if out ~= "" and string.lower(out):sub(1, 6) ~= "cyris" then
			run("say", function()
				chat(out)
				task.wait(2)
			end)
		end
		return true
	end

	-- exact-match commands
	local fn = exact[lower]
	if fn then
		fn()
		return true
	end

	-- Verity follow-up
	if waitingForParis and lower == "paris" then
		waitingForParis = false
		chat("ooui oui oui merci")
		return true
	end

	-- rose panini / rose <user>
	if lower:find("rose panini") then
		run("panini", paniniSpam)
		return true
	end
	local roseTarget = lower:match("^rose%s+(%S+)")
	if roseTarget then
		run("rose", function() rose(roseTarget) end)
		return true
	end

	if lower:find("secret switch") then
		chat("switches is the best")
		return true
	end

	if lower:find("what time is it") or lower:find("cyris time") or lower:find("cyris what time") or lower == "time" then
		run("time", tellTime)
		return true
	end

	return false
end

end -- end of all-in-one block


