	end
	-- 2) Average of SpawnLocations
	local sumX, sumZ, n = 0, 0, 0
	for _, d in ipairs(workspace:GetDescendants()) do
		if d:IsA("SpawnLocation") then
			sumX = sumX + d.Position.X
			sumZ = sumZ + d.Position.Z
			n = n + 1
		end
	end
	if n > 0 then
		cachedCenterXZ = Vector3.new(sumX / n, 0, sumZ / n)
		return cachedCenterXZ
	end
	-- 3) Largest flat floor-like part near origin-ish
	local best, bestArea = nil, 0
	for _, d in ipairs(workspace:GetDescendants()) do
		if d:IsA("BasePart") and d.Anchored and d.Size.X > 50 and d.Size.Z > 50 and d.Size.Y < 20 then
			local area = d.Size.X * d.Size.Z
			if area > bestArea then
				bestArea = area
				best = d
			end
		end
	end
	if best then
		cachedCenterXZ = Vector3.new(best.Position.X, 0, best.Position.Z)
		return cachedCenterXZ
	end
	-- 4) fallback
	cachedCenterXZ = Vector3.new(0, 0, 0)
	return cachedCenterXZ
end

local function getGround()
	if groundY then return groundY end
	local center = getMapCenterXZ()
	local bp = workspace:FindFirstChild("Baseplate")
	if bp and bp:IsA("BasePart") then
		groundY = bp.Position.Y + bp.Size.Y / 2
		return groundY
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = { LocalPlayer.Character }
	local hit = workspace:Raycast(Vector3.new(center.X, 2000, center.Z), Vector3.new(0, -5000, 0), params)
	if hit then
		groundY = hit.Position.Y
	else
		local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
		groundY = root and (root.Position.Y - 3) or 0
	end
	return groundY
end

-- ---------- infinite baseplate ----------
local infPart, infConn

local function enableInfinite()
	if infPart then return end
	local g = getGround()
	local bp = workspace:FindFirstChild("Baseplate")

	infPart = Instance.new("Part")
	infPart.Name = "CyrisInfiniteBaseplate"
	infPart.Anchored = true
	infPart.Locked = true
	infPart.TopSurface = Enum.SurfaceType.Smooth
	infPart.BottomSurface = Enum.SurfaceType.Smooth
	infPart.Size = Vector3.new(2048, 4, 2048)
	infPart.Position = Vector3.new(0, g - 0.05 - 2, 0)

	local copiedTexture = false
	if bp and bp:IsA("BasePart") then
		infPart.Color = bp.Color
		infPart.Material = bp.Material
		local tex = bp:FindFirstChildOfClass("Texture")
		if tex then
			tex:Clone().Parent = infPart
			copiedTexture = true
		end
	else
		infPart.Color = Color3.fromRGB(99, 95, 98)
	end
	if not copiedTexture then
		local tex = Instance.new("Texture")
		tex.Texture = "rbxassetid://6372755229"
		tex.Face = Enum.NormalId.Top
		tex.StudsPerTileU = 8
		tex.StudsPerTileV = 8
		tex.Transparency = 0.8
		tex.Parent = infPart
	end
	infPart.Parent = workspace

	pcall(function() workspace.FallenPartsDestroyHeight = -50000 end)

	local lastX, lastZ = 0, 0
	infConn = RunService.Heartbeat:Connect(function()
		local char = LocalPlayer.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root or not infPart then return end
		-- snap in multiples of 64 so the stud texture never slides
		local x = math.floor(root.Position.X / 64 + 0.5) * 64
		local z = math.floor(root.Position.Z / 64 + 0.5) * 64
		if x ~= lastX or z ~= lastZ then
			lastX, lastZ = x, z
			infPart.Position = Vector3.new(x, infPart.Position.Y, z)
		end
	end)
end

local function disableInfinite()
	if infConn then infConn:Disconnect() infConn = nil end
	if infPart then infPart:Destroy() infPart = nil end
end

-- ---------- treehouse (asset 125459331 + creepy restyle) ----------
local tree, treeBusy = nil, false
local DROP = 180
local TREE_SINK = 1 -- studs the base is buried into the floor (raise to sink it deeper)
local TREE_ASSET_ID = 125459331

local function moveModel(model, targetCF)
	if not model then return end
	pcall(function()
		if model.PrimaryPart then
			model:SetPrimaryPartCFrame(targetCF)
		else
			model:PivotTo(targetCF)
		end
	end)
end

local function ensurePrimary(model)
	if model.PrimaryPart then return model.PrimaryPart end
	local best, bestSize = nil, 0
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") then
			local s = p.Size.X * p.Size.Y * p.Size.Z
			if s > bestSize then
				bestSize = s
				best = p
			end
		end
	end
	if best then
		model.PrimaryPart = best
		return best
	end
	return nil
end

local function loadTreeAsset()
	local model = nil
	-- Prefer GetObjects (common in executors)
	local ok, result = pcall(function()
		if game.GetObjects then
			return game:GetObjects("rbxassetid://" .. tostring(TREE_ASSET_ID))
		end
		return nil
	end)
	if ok and type(result) == "table" and result[1] then
		model = result[1]
	end
	if not model then
		ok, result = pcall(function()
			return game:GetService("InsertService"):LoadAsset(TREE_ASSET_ID)
		end)
		if ok and result then
			if result:IsA("Model") then
				-- LoadAsset returns a container model; take first child model/folder
				local child = result:FindFirstChildOfClass("Model") or result:GetChildren()[1]
				model = child or result
			else
				model = result
			end
		end
	end
	if not model then
		return nil, "Could not load asset " .. tostring(TREE_ASSET_ID)
	end
	if not model:IsA("Model") then
		local wrap = Instance.new("Model")
		wrap.Name = "CyrisNest"
		model.Parent = wrap
		model = wrap
	end
	model.Name = "CyrisNest"
	return model, nil
end

local function makeCreepy(model)
	-- Kill scripts (they can break client)
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("BaseScript") or d:IsA("LocalScript") or d:IsA("Script") or d:IsA("ModuleScript") then
			pcall(function() d:Destroy() end)
		end
	end

	-- Creepy recolor + climbable
	local darkWood = Color3.fromRGB(28, 18, 12)
	local bark = Color3.fromRGB(42, 28, 18)
	local blood = Color3.fromRGB(90, 12, 18)
	local moss = Color3.fromRGB(22, 40, 18)
	local bone = Color3.fromRGB(180, 170, 150)

	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") then
			p.Anchored = true
			p.CanCollide = true
			p.CanTouch = true
			p.CanQuery = true
			-- darken materials
			local n = string.lower(p.Name)
			if p.Material == Enum.Material.Wood or p.Material == Enum.Material.WoodPlanks
				or n:find("wood") or n:find("trunk") or n:find("branch") or n:find("log") then
				p.Color = bark
				p.Material = Enum.Material.Wood
			elseif n:find("leaf") or n:find("foliage") or n:find("bush") then
				p.Color = moss
				p.Material = Enum.Material.Grass
			elseif n:find("stair") or n:find("step") or n:find("ladder") or n:find("rung") or n:find("plank") then
				p.Color = darkWood
				p.Material = Enum.Material.WoodPlanks
				p.CanCollide = true
			elseif n:find("roof") or n:find("floor") or n:find("wall") or n:find("platform") then
				p.Color = Color3.fromRGB(35, 22, 16)
				p.Material = Enum.Material.WoodPlanks
				p.CanCollide = true
			else
				-- general darken
				local c = p.Color
				p.Color = Color3.new(c.R * 0.35, c.G * 0.28, c.B * 0.25)
			end
		elseif p:IsA("Decal") or p:IsA("Texture") then
			p.Color3 = Color3.fromRGB(80, 40, 40)
			p.Transparency = math.min(p.Transparency + 0.15, 0.6)
		end
	end

	-- Add climbing-friendly parts: invisible thicker collision on thin ladders
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") then
			local n = string.lower(p.Name)
			if n:find("ladder") or n:find("rung") or n:find("step") or n:find("stair") then
				-- ensure thickness for climb
				if p.Size.Y < 1 and p.Size.X < 3 then
					p.Size = Vector3.new(math.max(p.Size.X, 2.5), math.max(p.Size.Y, 0.8), math.max(p.Size.Z, 2.5))
				end
				p.CanCollide = true
			end
		end
	end

	-- Atmosphere: red lanterns + fog particles near top
	local primary = ensurePrimary(model)
	local origin = primary and primary.Position or Vector3.new(0, 0, 0)
	local topY = origin.Y
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") and p.Position.Y > topY then
			topY = p.Position.Y
		end
	end

	for i = 1, 6 do
		local a = (i / 6) * math.pi * 2
		local pos = Vector3.new(origin.X + math.cos(a) * 18, topY - 4, origin.Z + math.sin(a) * 18)
		local bulb = Instance.new("Part")
		bulb.Name = "CyrisLantern"
		bulb.Shape = Enum.PartType.Ball
		bulb.Size = Vector3.new(1.4, 1.4, 1.4)
		bulb.Anchored = true
		bulb.CanCollide = false
		bulb.Material = Enum.Material.Neon
		bulb.Color = blood
		bulb.CFrame = CFrame.new(pos)
		bulb.Parent = model
		local light = Instance.new("PointLight")
		light.Color = Color3.fromRGB(180, 30, 40)
		light.Brightness = 2.2
		light.Range = 28
		light.Parent = bulb
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxassetid://241641144"
		pe.Color = ColorSequence.new(Color3.fromRGB(120, 20, 25), Color3.fromRGB(40, 0, 5))
		pe.Size = NumberSequence.new(0.4, 1.2)
		pe.Lifetime = NumberRange.new(1.5, 3)
		pe.Rate = 8
		pe.Speed = NumberRange.new(0.5, 1.5)
		pe.SpreadAngle = Vector2.new(30, 30)
		pe.Parent = bulb
	end

	-- Ground mist ring
	for i = 1, 8 do
		local a = (i / 8) * math.pi * 2
		local mist = Instance.new("Part")
		mist.Name = "Mist"
		mist.Size = Vector3.new(6, 1, 6)
		mist.Anchored = true
		mist.CanCollide = false
		mist.Transparency = 1
		mist.CFrame = CFrame.new(origin.X + math.cos(a) * 22, origin.Y - 8, origin.Z + math.sin(a) * 22)
		mist.Parent = model
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxassetid://241641144"
		pe.Color = ColorSequence.new(Color3.fromRGB(40, 50, 35), Color3.fromRGB(20, 25, 15))
		pe.Size = NumberSequence.new(4, 10)
		pe.Transparency = NumberSequence.new(0.4, 1)
		pe.Lifetime = NumberRange.new(3, 6)
		pe.Rate = 4
		pe.Speed = NumberRange.new(0.2, 0.8)
		pe.SpreadAngle = Vector2.new(180, 180)
		pe.Parent = mist
	end

	-- Billboard warning
	local bb = Instance.new("BillboardGui")
	bb.Size = UDim2.new(0, 200, 0, 40)
	bb.StudsOffset = Vector3.new(0, 12, 0)
	bb.AlwaysOnTop = false
	bb.MaxDistance = 200
	bb.Parent = primary or model
	local lab = Instance.new("TextLabel")
	lab.Size = UDim2.new(1, 0, 1, 0)
	lab.BackgroundTransparency = 1
	lab.Text = "THE NEST"
	lab.TextColor3 = Color3.fromRGB(180, 30, 40)
	lab.TextStrokeTransparency = 0.2
	lab.Font = Enum.Font.GothamBlack
	lab.TextScaled = true
	lab.Parent = bb

	return model
end

local function getModelBounds(model)
	local ok, cf, size = pcall(function()
		return model:GetBoundingBox()
	end)
	if ok and cf and size then
		return cf, size
	end
	-- manual bounds
	local minV = Vector3.new(math.huge, math.huge, math.huge)
	local maxV = Vector3.new(-math.huge, -math.huge, -math.huge)
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") then
			local pos = p.Position
			local h = p.Size * 0.5
			minV = Vector3.new(math.min(minV.X, pos.X - h.X), math.min(minV.Y, pos.Y - h.Y), math.min(minV.Z, pos.Z - h.Z))
			maxV = Vector3.new(math.max(maxV.X, pos.X + h.X), math.max(maxV.Y, pos.Y + h.Y), math.max(maxV.Z, pos.Z + h.Z))
		end
	end
	local center = (minV + maxV) * 0.5
	local size = maxV - minV
	return CFrame.new(center), size
end

-- Lowest point of the tree's REAL geometry. Ignores the invisible mist emitters and
-- lantern bulbs we add, which used to stretch the bounding box and lift the tree.
local function getRealBottom(model)
	local lowest = nil
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") and p.Name ~= "Mist" and p.Name ~= "CyrisLantern" and p.Transparency < 0.95 then
			local cf, sz = p.CFrame, p.Size
			local halfY = 0.5 * (math.abs(cf.RightVector.Y) * sz.X + math.abs(cf.UpVector.Y) * sz.Y + math.abs(cf.LookVector.Y) * sz.Z)
			local bottom = cf.Position.Y - halfY
			if not lowest or bottom < lowest then lowest = bottom end
		end
	end
	return lowest
end

local function shiftModel(model, delta)
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") then
			p.CFrame = p.CFrame + delta
		end
	end
end

local function buildTreehouse(g)
	local model, err = loadTreeAsset()
	if not model then
		warn("[Cyris] Tree load failed:", err)
		return nil
	end
	makeCreepy(model)
	local primary = ensurePrimary(model)
	if not primary then
		warn("[Cyris] Tree has no parts")
		model:Destroy()
		return nil
	end

	-- Parent first so world positions resolve, then snap to map MIDDLE
	model.Parent = workspace
	local centerXZ = getMapCenterXZ()
	local bboxCF, bboxSize = getModelBounds(model)
	local bottomY = bboxCF.Position.Y - bboxSize.Y * 0.5
	local targetCenter = Vector3.new(centerXZ.X, g + bboxSize.Y * 0.5, centerXZ.Z)
	local delta = targetCenter - bboxCF.Position
	-- also fix Y so lowest sits on ground
	local yFix = g - (bottomY + delta.Y)
	delta = delta + Vector3.new(0, yFix, 0)
	shiftModel(model, delta)

	-- Final exact center lock via PivotTo if available
	pcall(function()
		local cf, size = getModelBounds(model)
		local bottom = cf.Position.Y - size.Y * 0.5
		local goal = CFrame.new(centerXZ.X, g + size.Y * 0.5, centerXZ.Z)
		if model.PivotTo then
			model:PivotTo(goal)
		elseif model.PrimaryPart then
			local off = goal.Position - cf.Position
			shiftModel(model, off)
		end
	end)

	-- Seat the tree on the actual floor (real parts only), slightly buried
	local realBottom = getRealBottom(model)
	if realBottom then
		shiftModel(model, Vector3.new(0, (g - TREE_SINK) - realBottom, 0))
	end
	-- keep the mist ring down at ground level instead of hovering at an arbitrary height
	for _, p in ipairs(model:GetDescendants()) do
		if p:IsA("BasePart") and p.Name == "Mist" then
			p.CFrame = CFrame.new(p.Position.X, g + 1, p.Position.Z)
		end
	end

	print(string.format("[CYRIS] Treehouse centered at (%.1f, ground %.1f, %.1f)", centerXZ.X, g, centerXZ.Z))
	return model
end

local function raiseModel(model)
	if not model then return end
	local primary = ensurePrimary(model)
	if not primary then return end
	local centerXZ = getMapCenterXZ()
	-- Re-lock XZ to map middle before rising
	local bboxCF = select(1, getModelBounds(model))
	local centerDelta = Vector3.new(centerXZ.X - bboxCF.Position.X, 0, centerXZ.Z - bboxCF.Position.Z)
	shiftModel(model, centerDelta)
	primary = ensurePrimary(model)
	local base = primary.CFrame
	-- store base at final risen pose (already on ground)
	moveModel(model, base * CFrame.new(0, -DROP, 0))
	local t0 = os.clock()
	local dur = 7
	while os.clock() - t0 < dur do
		if not model.Parent then return end
		local a = math.min((os.clock() - t0) / dur, 1)
		local e = 1 - (1 - a) ^ 2.5
		local shake = (a > 0.7) and (math.sin(a * 55) * 0.35 * (1 - a)) or (math.sin(a * 12) * 0.08 * a)
		moveModel(model, base * CFrame.new(shake, -DROP * (1 - e), shake * 0.4))
		RunService.Heartbeat:Wait()
	end
	moveModel(model, base)
	-- final snap to center XZ
	local cf = select(1, getModelBounds(model))
	shiftModel(model, Vector3.new(centerXZ.X - cf.Position.X, 0, centerXZ.Z - cf.Position.Z))
end

local function lowerModel(model)
	if not model then return end
	local primary = ensurePrimary(model)
	if not primary then return end
	local base = primary.CFrame
	local t0 = os.clock()
	local dur = 4
	while os.clock() - t0 < dur do
		if not model.Parent then return end
		local a = math.min((os.clock() - t0) / dur, 1)
		moveModel(model, base * CFrame.new(0, -DROP * a, 0))
		RunService.Heartbeat:Wait()
	end
end

local function toggleTreehouse()
	if treeBusy then return end
	treeBusy = true
	local ok, err = pcall(function()
		if tree and tree.Parent then
			sendChat("CYRIS: The hollow tree returns to the dirt... for now.")
			pcall(function() lowerModel(tree) end)
			pcall(function() tree:Destroy() end)
			tree = nil
		else
			sendChat("CYRIS: Something stirs beneath the center of the map...")
			local g = getGround()
			tree = buildTreehouse(g)
			if tree and (tree.PrimaryPart or ensurePrimary(tree)) then
				raiseModel(tree)
				sendChat("CYRIS: The nest rises from the heart of the map. Climb if you dare.")
			else
				sendChat("CYRIS: The earth rejected the tree...")
				if tree then pcall(function() tree:Destroy() end) tree = nil end
			end
		end
	end)
	if not ok then
		warn("CYRIS treehouse error: " .. tostring(err))
		sendChat("CYRIS: Something went wrong in the dark... " .. tostring(err):sub(1, 80))
		tree = nil
	end
	treeBusy = false
end

-- ---------- hook into the command pipeline ----------
local prevAio = aioHandle
aioHandle = function(speaker, text)
	if prevAio(speaker, text) then return true end -- blacklist + older commands first
	if type(text) ~= "string" then return false end
	local lower = string.lower(text):gsub("^%s+", ""):gsub("%s+$", "")

	if lower:find("^cyris%s+light%s+up") then
		task.spawn(toggleTreehouse)
		return true
	end

	if lower:find("^cyris%s+refresh") or lower == "cyris change fit" or lower:find("^cyris%s+update%s+fit") then
		local msg = refreshFit()
		if msg then sendChat("CYRIS: " .. msg) end
		return true
	end

	if lower:find("^cyris%s+infinite") then
		if infPart then
			disableInfinite()
			sendChat("CYRIS: The endless ground cracks and sinks.")
		else
			enableInfinite()
			sendChat("CYRIS: The ground stretches forever. Nowhere left to fall.")
		end
		return true
	end

	return false
end

-- infinite floor is on by default
task.spawn(function()
	task.wait(1)
	pcall(enableInfinite)
end)

end -- end of treehouse / infinite baseplate block


