				packName = cs.packName or "Default",
				speed = cs.speed or 1,
				key = cyrisKeyName(cs.keyCode),
			})
		end
		local payload = {
			ownerUserId = LocalPlayer.UserId,
			ownerName = LocalPlayer.Name,
			ownerDisplay = LocalPlayer.DisplayName,
			nametagText = nametagText,
			nametagEnabled = nametagEnabled,
			reanimSpeed = reanimSpeed,
			statePackNames = statePackNames,
			stateSpeeds = stateSpeeds,
			animKeybinds = binds,
			speedKeybinds = speedBinds,
			customStates = custom,
			savedAt = os.time(),
		}
		writefile(CYRIS_CFG_FILE, HS:JSONEncode(payload))
	end)
	if not ok then
		warn("[CYRIS] save config failed:", err)
	end
end
local function loadCyrisConfig()
	local ok, data = pcall(function()
		if not readfile or not isfile then return nil end
		if not isfile(CYRIS_CFG_FILE) then return nil end
		local raw = readfile(CYRIS_CFG_FILE)
		if type(raw) ~= "string" or #raw < 5 then return nil end
		local HS = game:GetService("HttpService")
		return HS:JSONDecode(raw)
	end)
	if not ok or type(data) ~= "table" then return false end
	-- only apply if this is the same executor (or file is theirs)
	if data.ownerUserId and tonumber(data.ownerUserId) ~= LocalPlayer.UserId then
		print("[CYRIS] Config belongs to another user — ignoring")
		return false
	end
	if type(data.nametagText) == "string" and data.nametagText ~= "" then
		nametagText = data.nametagText
	end
	if data.nametagEnabled ~= nil then
		nametagEnabled = data.nametagEnabled and true or false
	end
	if type(data.reanimSpeed) == "number" and data.reanimSpeed > 0 then
		reanimSpeed = data.reanimSpeed
	end
	if type(data.statePackNames) == "table" then
		for k, v in pairs(data.statePackNames) do
			if type(k) == "string" and type(v) == "string" then
				statePackNames[k] = v
			end
		end
	end
	if type(data.stateSpeeds) == "table" then
		for k, v in pairs(data.stateSpeeds) do
			if type(k) == "string" and type(v) == "number" and v > 0 then
				stateSpeeds[k] = v
			end
		end
	end
	if type(data.animKeybinds) == "table" then
		animKeybinds = {}
		for kn, anim in pairs(data.animKeybinds) do
			local kc = cyrisKeyFromName(kn)
			if kc and type(anim) == "string" then
				animKeybinds[kc] = anim
			end
		end
	end
	if type(data.speedKeybinds) == "table" then
		speedKeybinds = {}
		for kn, spd in pairs(data.speedKeybinds) do
			local kc = cyrisKeyFromName(kn)
			if kc and type(spd) == "number" then
				speedKeybinds[kc] = spd
			end
		end
	end
	if type(data.customStates) == "table" then
		customStates = {}
		for _, cs in ipairs(data.customStates) do
			if type(cs) == "table" and type(cs.name) == "string" then
				table.insert(customStates, {
					name = cs.name,
					packName = cs.packName or "Default",
					data = nil, -- resolved later when library is ready
					speed = (type(cs.speed) == "number" and cs.speed > 0) and cs.speed or 1,
					keyCode = cyrisKeyFromName(cs.key),
				})
			end
		end
	end
	print("[CYRIS] Loaded saved config for " .. tostring(data.ownerName or LocalPlayer.Name))
	return true
end
-- Resolve pack data for states after ANIM_LIBRARY is filled
local function resolveStatePacksFromNames()
	local function findData(name)
		if not name or name == "Default" then return nil end
		for _, a in ipairs(ANIM_LIBRARY) do
			if a.name == name then
				if a.kind == "keyframe" and a.data then return a.data end
				if a.kind == "procedural" and PROCEDURAL[name] then
					return { __procedural = name }
				end
			end
		end
		return nil
	end
	for stateKey, packName in pairs(statePackNames) do
		stateKeyframePacks[stateKey] = findData(packName)
	end
	for _, cs in ipairs(customStates) do
		cs.data = findData(cs.packName)
	end
end

