local function setLocalHidden(model, hidden)
	if not model then return end
	local t = hidden and 1 or 0
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("BasePart") then
			if part.Name == "HumanoidRootPart" then
				part.LocalTransparencyModifier = 1
			else
				part.LocalTransparencyModifier = t
			end
		end
	end
	-- Also hide accessories' handles
	for _, acc in ipairs(model:GetChildren()) do
		if acc:IsA("Accoutrement") then
			for _, p in ipairs(acc:GetDescendants()) do
				if p:IsA("BasePart") then
					p.LocalTransparencyModifier = t
				end
			end
		end
	end
end

local function indexMotors(character)
	local map = {}
	for _, d in ipairs(character:GetDescendants()) do
		if d:IsA("Motor6D") and d.Part1 then
			map[d.Part1.Name] = d
			map[d.Name] = d
		end
	end
	return map
end

local function destroyClone()
	if reanimConn then
		pcall(function() reanimConn:Disconnect() end)
		reanimConn = nil
	end
	if reanimClone then
		pcall(function() reanimClone:Destroy() end)
		reanimClone = nil
	end
	cloneMotors = {}
end

local function restoreReal()
	local char = LocalPlayer.Character
	if char then
		setLocalHidden(char, false)
		local animate = char:FindFirstChild("Animate")
		if animate then
			pcall(function() animate.Disabled = false end)
		end
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum then
			pcall(function()
				hum.AutoRotate = true
				hum.PlatformStand = false
			end)
		end
		-- reset motor transforms
		for _, d in ipairs(char:GetDescendants()) do
			if d:IsA("Motor6D") then
				pcall(function() d.Transform = CFrame.new() end)
			end
		end
	end
end

local function createClone()
	local char = LocalPlayer.Character
	if not char then return nil, "No character" end
	local hum = char:FindFirstChildOfClass("Humanoid")
	local hrp = char:FindFirstChild("HumanoidRootPart")
	if not hum or not hrp then return nil, "Missing Humanoid/HRP" end

	destroyClone()

	char.Archivable = true
	local clone = char:Clone()
	char.Archivable = false
	clone.Name = "CyrisReanim"

	-- Prep clone
	local cAnimate = clone:FindFirstChild("Animate")
	if cAnimate then cAnimate:Destroy() end
	local cHum = clone:FindFirstChildOfClass("Humanoid")
	if cHum then
		cHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
		cHum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
		cHum.RequiresNeck = false
		cHum.BreakJointsOnDeath = false
		cHum.PlatformStand = true
		cHum.AutoRotate = false
		-- stop any tracks
		local animator = cHum:FindFirstChildOfClass("Animator")
		if animator then
			for _, t in ipairs(animator:GetPlayingAnimationTracks()) do
				pcall(function() t:Stop(0) end)
			end
		end
	end
	local ff = clone:FindFirstChildOfClass("ForceField")
	if ff then ff:Destroy() end

	-- Unanchor, no collision on clone (visual only)
	for _, p in ipairs(clone:GetDescendants()) do
		if p:IsA("BasePart") then
			p.Anchored = false
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Massless = true
			if p.Name == "HumanoidRootPart" then
				p.Anchored = true -- root stays put relative, we'll sync
			end
		end
		if p:IsA("BaseScript") or p:IsA("LocalScript") or p:IsA("Script") then
			p:Destroy()
		end
	end

	-- Position clone on real
	clone:PivotTo(char:GetPivot())
	clone.Parent = workspace

	-- Hide real body locally; show clone
	setLocalHidden(char, true)
	setLocalHidden(clone, false)

	-- Disable real Animate so it doesn't fight
	local rAnimate = char:FindFirstChild("Animate")
	if rAnimate then pcall(function() rAnimate.Disabled = true end) end

	cloneMotors = indexMotors(clone)
	realMotors = indexMotors(char)

	-- Sync loop: keep clone HRP aligned to real HRP so you can still walk
	reanimClone = clone
	task.defer(function()
		pcall(updateNametag)
	end)
	return clone, nil
end

local function lerpCF(a, b, t)
	return a:Lerp(b, math.clamp(t, 0, 1))
end

local function applyPose(motors, poses)
	for partName, cf in pairs(poses) do
		local m = motors[partName]
		if m then
			m.Transform = cf
		end
	end
end

