		"Astros_20fingering_202.lua", "Astros_20fingering_204.lua", "Astros_20flex.lua", "Astros_20foot_20idle.lua",
		"Astros_20grinding.lua", "Astros_20gripping_20ass_20dance.lua", "Astros_20heavinly_20fuck_202.lua",
		"Astros_20hump_2013.lua", "Astros_20hump_2017.lua", "Astros_20idle_203.lua", "Astros_20kitten_20dance.lua",
		"Astros_20kitten_20dance_202.lua", "BBoom_20BBoom_20_Part_202_.lua", "Back_20On_2074.lua",
		"Backflip.lua", "Backshots.lua", "Backstroke.lua", "Bad_20Boy.lua", "Bad_20Romance.lua",
		"Balka_20Ki_20maa.lua", "Baller.lua", "Ballerina.lua", "Ballet_20Montage.lua", "Baseball_20Bill.lua",
		"Bass_20Down_20Low.lua", "Bear_20Hug.lua", "Beat_20It.lua", "Bed_20Chem.lua", "Bed_20Chem_20II.lua",
		"Been_20Away.lua", "Beep_20Boop.lua", "Belly_20Dance.lua", "Belly_20Dancin_.lua", "Belly_20Spin.lua",
		"Better_20Than.lua", "Bhangra_20Boogie.lua", "Big_20Dawgs.lua",
		"a_thrust.lua", "a_thrust_2.lua", "anthony_thrust.lua", "ass_20slapped.lua", "back_slide.lua",
	}
	local SEARCH_PATHS = {
		"",
		"workspace/",
		"Workspace/",
		"keyframes/",
		"anims/",
		"Animations/",
		"folder/",
		"Folder/",
	}
	local function tryRead(path)
		local ok, data = pcall(function()
			if readfile then return readfile(path) end
			return nil
		end)
		if ok and type(data) == "string" and #data > 20 then return data end
		return nil
	end
	-- Parse both formats:
	-- 1) return { ["KeyframeSequence"] = { {Time=..,Data={}}, ... } }  or bare array
	-- 2) return { ["Anim Name"] = { {Time=..,Data={}}, ... } }  (folder .lua packs)
	local function parseKeyframeFile(raw)
		if not raw then return nil, nil end
		local src = raw
		if not src:find("return") then src = "return " .. src end
		local fn = loadstring(src)
		if not fn then return nil, nil end
		local ok, result = pcall(fn)
		if not ok or type(result) ~= "table" then return nil, nil end

		if result["KeyframeSequence"] and type(result["KeyframeSequence"]) == "table" and #result["KeyframeSequence"] >= 1 then
			return result["KeyframeSequence"], "KeyframeSequence"
		end
		if result[1] and type(result[1]) == "table" and result[1].Time ~= nil then
			return result, "Sequence"
		end

		local packs = {}
		for name, seq in pairs(result) do
			if type(name) == "string" and type(seq) == "table" and #seq >= 1 then
				local first = seq[1]
				if type(first) == "table" and (first.Time ~= nil or first.Data ~= nil) then
					table.insert(packs, { name = name, data = seq })
				end
			end
		end
		if #packs > 0 then return packs, "named" end
		return nil, nil
	end

	local function prettyFromFilename(fname)
		local pretty = fname
			:gsub("^custom_", "")
			:gsub("%.dat$", "")
			:gsub("%.lua$", "")
			:gsub("_20", " ")
			:gsub("_", " ")
			:gsub("%%20", " ")
		pretty = pretty:gsub("(%a)([%w_']*)", function(a, b) return a:upper() .. b:lower() end)
		return pretty
	end

	local loadedNames = {}
	local loaded = 0

	local function addPack(name, seq)
		if not name or not seq or #seq < 1 then return end
		if loadedNames[name] then return end
		loadedNames[name] = true
		table.insert(ANIM_LIBRARY, { name = name, kind = "keyframe", data = seq })
		loaded = loaded + 1
	end

	for _, fname in ipairs(KEYFRAME_FILES) do
		local seqOrPacks, kind = nil, nil
		for _, prefix in ipairs(SEARCH_PATHS) do
			local raw = tryRead(prefix .. fname)
			if raw then
				seqOrPacks, kind = parseKeyframeFile(raw)
				if seqOrPacks then break end
			end
		end
		if seqOrPacks then
			if kind == "named" then
				for _, p in ipairs(seqOrPacks) do
					addPack(p.name, p.data)
				end
			else
				addPack(prettyFromFilename(fname), seqOrPacks)
			end
		end
	end

	-- Discover extra packs via listfiles (Synapse/Fluxus/etc)
	local function tryList(dir)
		local ok, files = pcall(function()
			if listfiles then return listfiles(dir) end
			return nil
		end)
		if not ok or type(files) ~= "table" then return end
		for _, path in ipairs(files) do
			local lower = string.lower(tostring(path))
			if lower:match("%.dat$") or lower:match("%.lua$") then
				local raw = tryRead(path)
				if raw then
					local seqOrPacks, kind = parseKeyframeFile(raw)
					if seqOrPacks then
						if kind == "named" then
							for _, p in ipairs(seqOrPacks) do
								addPack(p.name, p.data)
							end
						else
							local base = tostring(path):match("([^/\\]+)$") or path
							addPack(prettyFromFilename(base), seqOrPacks)
						end
					end
				end
			end
		end
	end
	for _, dir in ipairs({ "", "workspace", "Workspace", "keyframes", "anims", "Animations", "folder", "Folder" }) do
		pcall(tryList, dir)
	end

	if loaded > 0 then
		print("[CYRIS] Auto-loaded " .. loaded .. " keyframe packs into reanim")
	else
		print("[CYRIS] No keyframe packs found — put .lua/.dat files in workspace/ or next to script")
	end
end

-- Load this executor's saved binds / states / nametag, then resolve keyframe data
pcall(function()
	loadCyrisConfig()
	resolveStatePacksFromNames()
end)

local function stopReanimation(silent)
	reanimActive = false
	forcedEmote = false
	activeCustomState = nil
	currentMode = nil
	currentSeq = nil
	currentProcName = nil
	pcall(function() RunService:UnbindFromRenderStep(REANIM_BIND_NAME) end)
	if reanimConn then
		pcall(function() reanimConn:Disconnect() end)
		reanimConn = nil
	end
	destroyClone()
	restoreReal()
	currentAnimName = "None"
	task.defer(function() pcall(updateNametag) end)
	if reanimGui then
		local st = reanimGui:FindFirstChild("StatusLabel", true)
		if st then
			st.Text = "Idle  ·  None"
			st.TextColor3 = Color3.fromRGB(130, 115, 120)
		end
		local dot = reanimGui:FindFirstChild("Dot", true)
		if dot then dot.BackgroundColor3 = Color3.fromRGB(130, 115, 120) end
		local playBtn = reanimGui:FindFirstChild("PlayBtn", true)
		if playBtn then playBtn.Text = "Play" end
	end
end

local function startStateMachine()
	if not ensureReanimated() then return false end
	forcedEmote = false
	reanimStartTime = os.clock()
	reanimActive = true
	currentMode = "states"
	currentAnimName = "States"
	startStep("states")
	if reanimGui then
		local st = reanimGui:FindFirstChild("StatusLabel", true)
		if st then
			st.Text = "States  ·  Idle/Walk/Run/Jump"
			st.TextColor3 = Color3.fromRGB(90, 230, 140)
		end
		local dot = reanimGui:FindFirstChild("Dot", true)
		if dot then dot.BackgroundColor3 = Color3.fromRGB(90, 230, 140) end
		local playBtn = reanimGui:FindFirstChild("PlayBtn", true)
		if playBtn then playBtn.Text = "Stop" end
	end
	return true
end

local function ensureReanimated()
	if reanimClone and reanimClone.Parent then
		return true
	end
	local clone, err = createClone()
	if not clone then
		warn("[Cyris] Reanim failed:", err)
		print("[CYRIS] Reanim failed: " .. tostring(err))
		return false
	end
	reanimActive = true
	return true
end

local function stopAllTracks(model)
	if not model then return end
	local hum = model:FindFirstChildOfClass("Humanoid")
	if not hum then return end
	local animator = hum:FindFirstChildOfClass("Animator")
	if not animator then
		pcall(function()
			for _, t in ipairs(hum:GetPlayingAnimationTracks()) do
				t:Stop(0)
			end
		end)
		return
	end
	pcall(function()
		for _, t in ipairs(animator:GetPlayingAnimationTracks()) do
			t:Stop(0)
		end
	end)
end

local function syncCloneRoot()
	local char = LocalPlayer.Character
	if not char or not reanimClone then return end
	local realHRP = char:FindFirstChild("HumanoidRootPart")
	local cloneHRP = reanimClone:FindFirstChild("HumanoidRootPart")
	if realHRP and cloneHRP then
		cloneHRP.CFrame = realHRP.CFrame
	end
	-- keep real body hidden, clone visible
	setLocalHidden(char, true)
	setLocalHidden(reanimClone, false)
	-- kill default anims every frame so they don't fight transforms
	stopAllTracks(char)
	stopAllTracks(reanimClone)
end

local function applyKeyframeAt(seq, t, motors)
	if not seq or #seq < 1 then return end
	if #seq == 1 then
		if seq[1].Data then
			for partName, cf in pairs(seq[1].Data) do
				local motor = motors[partName]
				if motor and typeof(cf) == "CFrame" then
					motor.Transform = cf
				end
			end
		end
		return
	end
	local duration = seq[#seq].Time or 1
	if duration <= 0 then duration = 1 end
	local tt = reanimLoop and (t % duration) or math.min(t, duration)

	local prev, nextKf = seq[1], seq[2]
	for i = 1, #seq - 1 do
		if (seq[i].Time or 0) <= tt and (seq[i + 1].Time or 0) >= tt then
			prev, nextKf = seq[i], seq[i + 1]
			break
		end
	end
	if tt >= (seq[#seq].Time or 0) then
		prev, nextKf = seq[#seq], seq[#seq]
	end

	local alpha = 0
	local dt = (nextKf.Time or 0) - (prev.Time or 0)
	if dt > 1e-6 then
		alpha = math.clamp((tt - (prev.Time or 0)) / dt, 0, 1)
	end

	if prev.Data and nextKf.Data then
		for partName, cfA in pairs(prev.Data) do
			if typeof(cfA) == "CFrame" then
				local cfB = nextKf.Data[partName]
				local motor = motors[partName]
				if motor and typeof(cfB) == "CFrame" then
					motor.Transform = lerpCF(cfA, cfB, alpha)
				elseif motor then
					motor.Transform = cfA
				end
			end
		end
	end
end

local function detectState()
	local char = LocalPlayer.Character
	if not char then return "Idle" end
	local hum = char:FindFirstChildOfClass("Humanoid")
	if not hum then return "Idle" end
	local st = hum:GetState()
	if st == Enum.HumanoidStateType.Jumping or st == Enum.HumanoidStateType.Freefall then
		return "Jump"
	end
	local moving = hum.MoveDirection.Magnitude > 0.08 and hum.WalkSpeed > 0.5
	if moving then
		-- Walk when slower, Run when faster (threshold ~14 default walk is 16)
		local spd = hum.WalkSpeed
		if spd >= 18 then
			return "Run"
		end
		return "Walk"
	end
	return "Idle"
end

local function stepKeyframe()
	if not reanimClone or not reanimClone.Parent then
		stopReanimation(true)
		return
	end
	syncCloneRoot()
	local elapsed = (os.clock() - reanimStartTime) * reanimSpeed
	applyKeyframeAt(currentSeq, elapsed, cloneMotors)
end

local function stepProcedural()
	if not reanimClone or not reanimClone.Parent then
		stopReanimation(true)
		return
	end
	syncCloneRoot()
	local fn = PROCEDURAL[currentProcName]
	if fn then
		local t = (os.clock() - reanimStartTime) * reanimSpeed
		fn(t, cloneMotors)
	end
end

local function stepStates()
	if not reanimClone or not reanimClone.Parent then
		stopReanimation(true)
		return
	end
	syncCloneRoot()

	-- Custom state (keybind-held or toggled) overrides movement states
	if activeCustomState then
		for _, cs in ipairs(customStates) do
			if cs.name == activeCustomState then
				currentStateName = cs.name
				local spd = (cs.speed or 1) * reanimSpeed
				local t = (os.clock() - reanimStartTime) * spd
				if cs.data and type(cs.data) == "table" and #cs.data >= 2 then
					applyKeyframeAt(cs.data, t, cloneMotors)
				elseif cs.packName and PROCEDURAL[cs.packName] then
					PROCEDURAL[cs.packName](t, cloneMotors)
				end
				return
			end
		end
	end

	local state = detectState()
	currentStateName = state
	local mult = stateSpeeds[state] or 1
	local t = (os.clock() - reanimStartTime) * reanimSpeed * mult
	local pack = stateKeyframePacks[state]
	if pack and type(pack) == "table" then
		if pack.__procedural and PROCEDURAL[pack.__procedural] then
			PROCEDURAL[pack.__procedural](t, cloneMotors)
		elseif #pack >= 2 then
			applyKeyframeAt(pack, t, cloneMotors)
		else
			local fn = PROCEDURAL[state]
			if fn then fn(t, cloneMotors) end
		end
	else
		local fn = PROCEDURAL[state]
		if fn then fn(t, cloneMotors) end
	end
end

local function startStep(mode)
	pcall(function() RunService:UnbindFromRenderStep(REANIM_BIND_NAME) end)
	if reanimConn then
		pcall(function() reanimConn:Disconnect() end)
		reanimConn = nil
	end
	local fn
	if mode == "keyframe" then
		fn = stepKeyframe
	elseif mode == "states" then
		fn = stepStates
	else
		fn = stepProcedural
	end
	-- Prefer BindToRenderStep at Last priority (overrides Animate)
	local bound = false
	pcall(function()
		RunService:BindToRenderStep(REANIM_BIND_NAME, Enum.RenderPriority.Last.Value, fn)
		bound = true
	end)
	if not bound then
		reanimConn = RunService.RenderStepped:Connect(fn)
	end
end

local function playKeyframeSequence(sequence, name)
	if not sequence or type(sequence) ~= "table" or #sequence < 2 then
		warn("[Cyris] Bad keyframe data")
		return false
	end
	if not ensureReanimated() then return false end

	local seq = {}
	for i, kf in ipairs(sequence) do seq[i] = kf end
	table.sort(seq, function(a, b) return (a.Time or 0) < (b.Time or 0) end)

	-- Reset transforms on clone
	for _, m in pairs(cloneMotors) do
		if typeof(m) == "Instance" then
			pcall(function() m.Transform = CFrame.new() end)
		end
	end

	reanimStartTime = os.clock()
	reanimActive = true
	forcedEmote = true
	currentMode = "keyframe"
	currentSeq = seq
	currentAnimName = name or "Custom"

	startStep("keyframe")

	if reanimGui then
		local st = reanimGui:FindFirstChild("StatusLabel", true)
		if st then
			st.Text = "Playing  ·  " .. currentAnimName
			st.TextColor3 = Color3.fromRGB(90, 230, 140)
		end
		local dot = reanimGui:FindFirstChild("Dot", true)
		if dot then dot.BackgroundColor3 = Color3.fromRGB(90, 230, 140) end
		local playBtn = reanimGui:FindFirstChild("PlayBtn", true)
		if playBtn then playBtn.Text = "Stop" end
	end
	return true
end

local function playProcedural(name)
	if not PROCEDURAL[name] then return false end
	if not ensureReanimated() then return false end

	for _, m in pairs(cloneMotors) do
		if typeof(m) == "Instance" then
			pcall(function() m.Transform = CFrame.new() end)
		end
	end

	reanimStartTime = os.clock()
	reanimActive = true
	forcedEmote = true
	currentMode = "procedural"
	currentProcName = name
	currentAnimName = name

	startStep("procedural")

	if reanimGui then
		local st = reanimGui:FindFirstChild("StatusLabel", true)
		if st then
			st.Text = "Playing  ·  " .. currentAnimName
			st.TextColor3 = Color3.fromRGB(90, 230, 140)
		end
		local dot = reanimGui:FindFirstChild("Dot", true)
		if dot then dot.BackgroundColor3 = Color3.fromRGB(90, 230, 140) end
		local playBtn = reanimGui:FindFirstChild("PlayBtn", true)
		if playBtn then playBtn.Text = "Stop" end
	end
	return true
end

local function playByName(name)
	for _, anim in ipairs(ANIM_LIBRARY) do
		if anim.name == name then
			if anim.kind == "keyframe" and anim.data then
				return playKeyframeSequence(anim.data, anim.name)
			elseif anim.kind == "procedural" then
				return playProcedural(anim.name)
			end
		end
	end
	return false
end

local function tryLoadPastedKeyframes(text)
	if type(text) ~= "string" or #text < 10 then
		return nil, "Too short"
	end
	local src = text
	if not src:find("return") then
		src = "return " .. src
	end
	local fn, err = loadstring(src)
	if not fn then
		return nil, "Parse: " .. tostring(err):sub(1, 50)
	end
	local ok, result = pcall(fn)
	if not ok then
		return nil, "Run: " .. tostring(result):sub(1, 50)
	end
	local seq = result
	if type(result) == "table" and result["KeyframeSequence"] then
		seq = result["KeyframeSequence"]
	end
	if type(seq) ~= "table" or #seq < 2 then
		return nil, "Need 2+ keyframes"
	end
	return seq, nil
end

-- ==================== GUI ====================
local function destroyReanimGui()
	if reanimGui then
		pcall(function() reanimGui:Destroy() end)
		reanimGui = nil
	end
end

local function createReanimMenu()
	destroyReanimGui()
	local pg = LocalPlayer:FindFirstChild("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui", 5)
	if not pg then return end

	local gui = Instance.new("ScreenGui")
	gui.Name = "CyrisReanimate"
	gui.ResetOnSpawn = false
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.IgnoreGuiInset = true
	gui.Parent = pg
	reanimGui = gui

	-- CYRIS_READABLE: let the art show through panels, keep text legible on top of it
	do
		local function tone(c)
			local r, g, b = math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)
			return r == g and g == b and (r == 8 or r == 16 or r == 26)
		end
		local function bright(c) return (c.R + c.G + c.B) / 3 > 0.62 end
		local function fix(d)
			if not d:IsA("GuiObject") then return end
			if tone(d.BackgroundColor3) and d.BackgroundTransparency < 0.55 then
				d.BackgroundTransparency = 0.55
			end
			if d:IsA("TextButton") or d:IsA("TextLabel") or d:IsA("TextBox") then
				local onBright = d:IsA("TextButton") and d.BackgroundTransparency < 0.5 and bright(d.BackgroundColor3)
				if onBright then
					d:SetAttribute("cyrisFlip", true)
					d.TextColor3 = Color3.fromRGB(0, 0, 0)
					d.TextStrokeTransparency = 1
				else
					if d:GetAttribute("cyrisFlip") then
						d:SetAttribute("cyrisFlip", nil)
						d.TextColor3 = Color3.fromRGB(255, 255, 255)
					end
					d.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
					d.TextStrokeTransparency = 0.5
				end
			end
		end
		local function hook(d)
			if not d:IsA("GuiObject") then return end
			if not d:GetAttribute("cyrisStyled") then
				d:SetAttribute("cyrisStyled", true)
				if d:IsA("TextButton") then
					d:GetPropertyChangedSignal("BackgroundColor3"):Connect(function() fix(d) end)
				end
			end
			fix(d)
		end
		for _, d in ipairs(gui:GetDescendants()) do pcall(hook, d) end
		gui.DescendantAdded:Connect(function(d) task.defer(function() pcall(hook, d) end) end)
		task.delay(0.6, function() for _, d in ipairs(gui:GetDescendants()) do pcall(fix, d) end end)
		task.delay(2, function() for _, d in ipairs(gui:GetDescendants()) do pcall(fix, d) end end)
	end

	local T = {
		bg       = Color3.fromRGB(0, 0, 0),
		panel    = Color3.fromRGB(8, 8, 8),
		card     = Color3.fromRGB(16, 16, 16),
		button   = Color3.fromRGB(26, 26, 26),
		hover    = Color3.fromRGB(60, 60, 60),
		accent   = Color3.fromRGB(255, 255, 255),
		accent2  = Color3.fromRGB(215, 215, 215),
		text     = Color3.fromRGB(255, 255, 255),
		dim      = Color3.fromRGB(170, 170, 170),
		green    = Color3.fromRGB(255, 255, 255),
		gold     = Color3.fromRGB(255, 255, 255),
		stroke   = Color3.fromRGB(255, 255, 255),
	}

	local function corner(p, r)
		local c = Instance.new("UICorner")
		c.CornerRadius = UDim.new(0, r or 8)
		c.Parent = p
		return c
	end
	local function stroke(p, col, th)
		local s = Instance.new("UIStroke")
		s.Color = col or T.stroke
		s.Thickness = th or 1
		s.Transparency = 0.25
		s.Parent = p
		return s
	end
	local function pad(p, n)
		local u = Instance.new("UIPadding")
		u.PaddingTop = UDim.new(0, n)
		u.PaddingBottom = UDim.new(0, n)
		u.PaddingLeft = UDim.new(0, n)
		u.PaddingRight = UDim.new(0, n)
		u.Parent = p
		return u
	end

	-- Main shell
	local main = Instance.new("Frame")
	main.Name = "Main"
	main.Size = UDim2.new(0, 280, 0, 460)
	main.Position = UDim2.new(1, -300, 0.5, -230)
	main.BackgroundColor3 = T.bg
	main.BorderSizePixel = 0
	main.Active = true
	main.ClipsDescendants = true
	main.Parent = gui
	corner(main, 14)
	local mainStroke = stroke(main, T.accent, 1.5)
	mainStroke.Transparency = 0.2

	-- Anime girl background (same local files as main menu)
	local function loadLocalReanim(path)
		local ok, result = pcall(function()
			if getcustomasset then return getcustomasset(path) end
			if syn and syn.getcustomasset then return syn.getcustomasset(path) end
			return nil
		end)
		if ok and result and result ~= "" then return result end
		return nil
	end
	local reanimBgAsset = CYRIS_ANIME_BG or (
		loadLocalReanim("cyris_bg.jpg") or loadLocalReanim("cyris_bg.gif") or loadLocalReanim("cyris_bg.png")
		or loadLocalReanim("anime_girl.png") or loadLocalReanim("anime.png")
		or loadLocalReanim("girl.png")
	)
	if reanimBgAsset then
		local rbg = Instance.new("ImageLabel")
		rbg.Name = "AnimeBG"
		rbg.Size = UDim2.new(1, 0, 1, 0)
		rbg.BackgroundTransparency = 1
		rbg.Image = reanimBgAsset
		rbg.ImageTransparency = 0
		rbg.ScaleType = Enum.ScaleType.Crop
		rbg.ZIndex = 0
		rbg.Parent = main
		local rvig = Instance.new("Frame")
		rvig.Size = UDim2.new(1, 0, 1, 0)
