	local openDropdown = nil
	local openCloser = nil

	local function listAllAnimNames()
		-- Default + every library entry (keyframes preferred, procedurals listed too)
		local names = { "Default" }
		local seen = { Default = true }
		for _, a in ipairs(ANIM_LIBRARY) do
			if a.name and not seen[a.name] then
				seen[a.name] = true
				table.insert(names, a.name)
			end
		end
		return names
	end

	local function getAnimDataByName(name)
		if not name or name == "Default" then return nil, nil end
		for _, a in ipairs(ANIM_LIBRARY) do
			if a.name == name then
				if a.kind == "keyframe" and a.data and type(a.data) == "table" and #a.data >= 2 then
					return a.data, a.name
				end
				-- procedural: store packName so stepStates can call PROCEDURAL
				return nil, a.name
			end
		end
		return nil, nil
	end

	local function makeDropAssign(parent, getName, setName, layoutOrder)
		local wrap = Instance.new("Frame")
		wrap.Size = UDim2.new(1, 0, 0, 32)
		wrap.BackgroundTransparency = 1
		wrap.LayoutOrder = layoutOrder
		wrap.Parent = parent
		wrap.ZIndex = 5

		local dropBtn = Instance.new("TextButton")
		dropBtn.Size = UDim2.new(1, 0, 1, 0)
		dropBtn.BackgroundColor3 = T.card
		dropBtn.Text = "  " .. (getName() or "Default") .. "  ▼"
		dropBtn.TextColor3 = T.text
		dropBtn.Font = Enum.Font.GothamMedium
		dropBtn.TextSize = 12
		dropBtn.TextXAlignment = Enum.TextXAlignment.Left
		dropBtn.Parent = wrap
		corner(dropBtn, 8)
		stroke(dropBtn, T.stroke, 1)

		-- Floating dropdown panel (search + list)
		local listFrame = Instance.new("Frame")
		listFrame.Size = UDim2.new(1, 0, 0, 0)
		listFrame.Position = UDim2.new(0, 0, 1, 2)
		listFrame.BackgroundColor3 = Color3.fromRGB(11, 11, 11)
		listFrame.BorderSizePixel = 0
		listFrame.Visible = false
		listFrame.ZIndex = 50
		listFrame.ClipsDescendants = true
		listFrame.Parent = wrap
		corner(listFrame, 8)
		stroke(listFrame, T.accent, 1)

		local searchBox = Instance.new("TextBox")
		searchBox.Name = "Search"
		searchBox.Size = UDim2.new(1, -8, 0, 28)
		searchBox.Position = UDim2.new(0, 4, 0, 4)
		searchBox.BackgroundColor3 = Color3.fromRGB(21, 21, 21)
		searchBox.Text = ""
		searchBox.PlaceholderText = "Search keyframes..."
		searchBox.PlaceholderColor3 = T.dim
		searchBox.TextColor3 = T.text
		searchBox.Font = Enum.Font.Gotham
		searchBox.TextSize = 12
		searchBox.ClearTextOnFocus = false
		searchBox.ZIndex = 51
		searchBox.Parent = listFrame
		corner(searchBox, 6)

		local scroll = Instance.new("ScrollingFrame")
		scroll.Size = UDim2.new(1, -4, 1, -40)
		scroll.Position = UDim2.new(0, 2, 0, 36)
		scroll.BackgroundTransparency = 1
		scroll.BorderSizePixel = 0
		scroll.ScrollBarThickness = 3
		scroll.ScrollBarImageColor3 = T.accent
		scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
		scroll.ZIndex = 51
		scroll.Parent = listFrame
		local ll = Instance.new("UIListLayout")
		ll.Padding = UDim.new(0, 2)
		ll.Parent = scroll
		local lp = Instance.new("UIPadding")
		lp.PaddingTop = UDim.new(0, 2)
		lp.PaddingBottom = UDim.new(0, 4)
		lp.PaddingLeft = UDim.new(0, 4)
		lp.PaddingRight = UDim.new(0, 4)
		lp.Parent = scroll

		-- ZIndexBehavior.Sibling only compares siblings, so the NEXT state card used to
		-- paint over this list. While open, lift this whole row above its siblings.
		local raised = {}
		local function raiseRow()
			local a = wrap.Parent
			while a and a:IsA("GuiObject") do
				table.insert(raised, { a, a.ZIndex })
				a.ZIndex = 100
				if a.Parent and a.Parent:IsA("ScrollingFrame") then break end
				a = a.Parent
			end
		end
		local function lowerRow()
			for _, r in ipairs(raised) do
				pcall(function() r[1].ZIndex = r[2] end)
			end
			raised = {}
		end

		local function closeList()
			listFrame.Visible = false
			listFrame.Size = UDim2.new(1, 0, 0, 0)
			lowerRow()
			if openDropdown == listFrame then openDropdown = nil end
			if openCloser == closeList then openCloser = nil end
		end

		local function fillList(filter)
			for _, c in ipairs(scroll:GetChildren()) do
				if c:IsA("TextButton") then c:Destroy() end
			end
			local names = listAllAnimNames()
			local cur = getName() or "Default"
			local q = string.lower(filter or "")
			local count = 0
			for _, n in ipairs(names) do
				if q == "" or string.find(string.lower(n), q, 1, true) then
					count = count + 1
					local item = Instance.new("TextButton")
					item.Size = UDim2.new(1, 0, 0, 26)
					item.BackgroundColor3 = (n == cur) and T.accent or Color3.fromRGB(18, 18, 18)
					item.Text = "  " .. n
					item.TextColor3 = T.text
					item.Font = Enum.Font.Gotham
					item.TextSize = 12
					item.TextXAlignment = Enum.TextXAlignment.Left
					item.ZIndex = 52
					item.Parent = scroll
					corner(item, 4)
					item.MouseButton1Click:Connect(function()
						setName(n)
						dropBtn.Text = "  " .. n .. "  ▼"
						closeList()
					end)
				end
			end
			if count == 0 then
				local empty = Instance.new("TextButton")
				empty.Size = UDim2.new(1, 0, 0, 26)
				empty.BackgroundTransparency = 1
				empty.Text = "  No matches"
				empty.TextColor3 = T.dim
				empty.Font = Enum.Font.Gotham
				empty.TextSize = 12
				empty.TextXAlignment = Enum.TextXAlignment.Left
				empty.ZIndex = 52
				empty.Parent = scroll
			end
		end

		searchBox:GetPropertyChangedSignal("Text"):Connect(function()
			fillList(searchBox.Text)
		end)

		dropBtn.MouseButton1Click:Connect(function()
			if listFrame.Visible then
				closeList()
				return
			end
			if openDropdown and openDropdown ~= listFrame then
				if openCloser then
					pcall(openCloser)
				else
					openDropdown.Visible = false
					openDropdown.Size = UDim2.new(1, 0, 0, 0)
				end
			end
			searchBox.Text = ""
			fillList("")
			raiseRow()
			-- fit inside the scroll area: open downward, or upward if there's more room above
			local listH, goUp = 180, false
			pcall(function()
				local sc = wrap.Parent
				while sc and not sc:IsA("ScrollingFrame") do sc = sc.Parent end
				if sc then
					local below = (sc.AbsolutePosition.Y + sc.AbsoluteSize.Y) - (wrap.AbsolutePosition.Y + wrap.AbsoluteSize.Y) - 6
					local above = wrap.AbsolutePosition.Y - sc.AbsolutePosition.Y - 6
					if below < 180 and above > below then
						goUp = true
						listH = math.clamp(above, 90, 180)
					else
						listH = math.clamp(below, 90, 180)
					end
				end
			end)
			listFrame.Position = goUp and UDim2.new(0, 0, 0, -(listH + 2)) or UDim2.new(0, 0, 1, 2)
			listFrame.Size = UDim2.new(1, 0, 0, listH)
			listFrame.Visible = true
			openDropdown = listFrame
			openCloser = closeList
			pcall(function() searchBox:CaptureFocus() end)
		end)
		return dropBtn
	end


