		spdLbl.Font = Enum.Font.Gotham
		spdLbl.TextSize = 11
		spdLbl.Parent = card

		local spdBox = Instance.new("TextBox")
		spdBox.Size = UDim2.new(0, 56, 0, 24)
		spdBox.Position = UDim2.new(1, -66, 0, 5)
		spdBox.BackgroundColor3 = T.card
		spdBox.Text = tostring(stateSpeeds[stateKey] or 1)
		spdBox.PlaceholderText = "1"
		spdBox.PlaceholderColor3 = T.dim
		spdBox.TextColor3 = T.text
		spdBox.Font = Enum.Font.GothamBold
		spdBox.TextSize = 12
		spdBox.ClearTextOnFocus = false
		spdBox.Parent = card
		corner(spdBox, 6)
		spdBox.FocusLost:Connect(function()
			local v = tonumber(spdBox.Text)
			if v and v > 0 then
				stateSpeeds[stateKey] = math.clamp(v, 0.05, 10)
				spdBox.Text = tostring(stateSpeeds[stateKey])
				pcall(saveCyrisConfig)
			else
				spdBox.Text = tostring(stateSpeeds[stateKey] or 1)
			end
		end)

		local dropHost = Instance.new("Frame")
		dropHost.Size = UDim2.new(1, -20, 0, 32)
		dropHost.Position = UDim2.new(0, 10, 0, 36)
		dropHost.BackgroundTransparency = 1
		dropHost.Parent = card
		makeDropAssign(dropHost, function()
			return statePackNames[stateKey] or "Default"
		end, function(n)
			statePackNames[stateKey] = n
			local data, pname = getAnimDataByName(n)
			if data then
				stateKeyframePacks[stateKey] = data
			elseif n == "Default" then
				stateKeyframePacks[stateKey] = nil
			else
				stateKeyframePacks[stateKey] = nil
				if PROCEDURAL[n] and n ~= stateKey then
					stateKeyframePacks[stateKey] = { __procedural = n }
				end
			end
			pcall(saveCyrisConfig)
		end, 1)
	end

