			sub.TextSize = 11
			sub.TextXAlignment = Enum.TextXAlignment.Left
			sub.Parent = row

			local bindB = Instance.new("TextButton")
			bindB.Size = UDim2.new(0, 40, 0, 22)
			bindB.Position = UDim2.new(1, -84, 0.5, -11)
			bindB.BackgroundColor3 = T.accent2
			bindB.Text = "Key"
			bindB.TextColor3 = Color3.new(1, 1, 1)
			bindB.Font = Enum.Font.GothamBold
			bindB.TextSize = 11
			bindB.Parent = row
			corner(bindB, 5)
			bindB.MouseButton1Click:Connect(function()
				waitingForStateBind = true
				pendingStateBindName = cs.name
				waitingForBind = nil
				waitingForSpeedBind = false
				bindB.Text = "..."
				local conn
				conn = UserInputService.InputBegan:Connect(function(input, gp)
					if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
					if input.KeyCode == Enum.KeyCode.Escape then
						waitingForStateBind = false
						pendingStateBindName = nil
						bindB.Text = "Key"
						conn:Disconnect()
						return
					end
					cs.keyCode = input.KeyCode
					animKeybinds[input.KeyCode] = nil
					speedKeybinds[input.KeyCode] = nil
					waitingForStateBind = false
					pendingStateBindName = nil
					conn:Disconnect()
					refreshCustomStateList()
					pcall(saveCyrisConfig)
				end)
			end)

			local delB = Instance.new("TextButton")
			delB.Size = UDim2.new(0, 28, 0, 22)
			delB.Position = UDim2.new(1, -38, 0.5, -11)
			delB.BackgroundColor3 = T.card
			delB.Text = "X"
			delB.TextColor3 = T.dim
			delB.Font = Enum.Font.GothamBold
			delB.TextSize = 12
			delB.Parent = row
			corner(delB, 5)
			delB.MouseButton1Click:Connect(function()
				for i, x in ipairs(customStates) do
					if x.name == cs.name then
						table.remove(customStates, i)
						break
					end
				end
				if activeCustomState == cs.name then activeCustomState = nil end
				refreshCustomStateList()
				pcall(saveCyrisConfig)
			end)
		end
	end

