	function refreshSpeedBinds()
		for _, c in ipairs(speedBindsHost:GetChildren()) do
			if c:IsA("Frame") then c:Destroy() end
		end
		local entries = {}
		for kc, spd in pairs(speedKeybinds) do
			table.insert(entries, { kc = kc, spd = spd })
		end
		table.sort(entries, function(a, b) return a.spd < b.spd end)
		if #entries == 0 then
			local empty = Instance.new("TextLabel")
			empty.Size = UDim2.new(1, 0, 0, 24)
			empty.BackgroundTransparency = 1
			empty.Text = "No speed binds yet"
			empty.TextColor3 = T.dim
			empty.Font = Enum.Font.Gotham
			empty.TextSize = 11
			empty.TextXAlignment = Enum.TextXAlignment.Left
			empty.Parent = speedBindsHost
			return
		end
		for _, e in ipairs(entries) do
			local row = Instance.new("Frame")
			row.Size = UDim2.new(1, 0, 0, 30)
			row.BackgroundColor3 = T.button
			row.BorderSizePixel = 0
			row.Parent = speedBindsHost
