			x.Position = UDim2.new(1, -34, 0.5, -11)
			x.BackgroundColor3 = T.card
			x.Text = "X"
			x.TextColor3 = T.dim
			x.Font = Enum.Font.GothamBold
			x.TextSize = 12
			x.Parent = row
			corner(x, 4)
			x.MouseButton1Click:Connect(function()
				speedKeybinds[e.kc] = nil
				refreshSpeedBinds()
			end)
		end
	end
