		for _, c in ipairs(bindsScroll:GetChildren()) do
			if c:IsA("Frame") or (c:IsA("TextLabel") and c ~= bindsHint) then
				c:Destroy()
			end
		end
		local byAnim = reverseBinds()
		for i, anim in ipairs(ANIM_LIBRARY) do
			local row = Instance.new("Frame")
			row.Size = UDim2.new(1, -4, 0, 36)
