			nameL.Position = UDim2.new(0, 10, 0, 0)
			nameL.BackgroundTransparency = 1
			nameL.Text = anim.name
			nameL.TextColor3 = T.text
			nameL.Font = Enum.Font.GothamMedium
			nameL.TextSize = 12
			nameL.TextXAlignment = Enum.TextXAlignment.Left
			nameL.Parent = row

			local keyL = Instance.new("TextLabel")
			keyL.Name = "KeyLabel"
			keyL.Size = UDim2.new(0, 70, 0, 24)
			keyL.Position = UDim2.new(0.48, 0, 0.5, -12)
			keyL.BackgroundColor3 = T.card
			keyL.Text = keyName(byAnim[anim.name])
			keyL.TextColor3 = byAnim[anim.name] and T.gold or T.dim
			keyL.Font = Enum.Font.GothamBold
			keyL.TextSize = 11
			keyL.Parent = row
			corner(keyL, 6)

			local bindBtn = Instance.new("TextButton")
			bindBtn.Size = UDim2.new(0, 52, 0, 24)
			bindBtn.Position = UDim2.new(1, -100, 0.5, -12)
			bindBtn.BackgroundColor3 = T.accent2
			bindBtn.Text = "Bind"
			bindBtn.TextColor3 = Color3.new(1,1,1)
			bindBtn.Font = Enum.Font.GothamBold
			bindBtn.TextSize = 11
			bindBtn.Parent = row
			corner(bindBtn, 6)

			local clearBtn = Instance.new("TextButton")
			clearBtn.Size = UDim2.new(0, 36, 0, 24)
			clearBtn.Position = UDim2.new(1, -42, 0.5, -12)
			clearBtn.BackgroundColor3 = T.button
			clearBtn.Text = "X"
			clearBtn.TextColor3 = T.dim
			clearBtn.Font = Enum.Font.GothamBold
			clearBtn.TextSize = 12
			clearBtn.Parent = row
			corner(clearBtn, 6)

			bindBtn.MouseButton1Click:Connect(function()
				waitingForBind = anim.name
				keyL.Text = "..."
				keyL.TextColor3 = T.accent
				bindBtn.Text = "..."
				-- one-shot capture
				local conn
				conn = UserInputService.InputBegan:Connect(function(input, gp)
					if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
					if input.KeyCode == Enum.KeyCode.Escape then
						waitingForBind = nil
						keyL.Text = keyName(byAnim[anim.name])
						keyL.TextColor3 = byAnim[anim.name] and T.gold or T.dim
						bindBtn.Text = "Bind"
						conn:Disconnect()
						return
					end
					-- remove old bind for this key
					animKeybinds[input.KeyCode] = anim.name
					for kc, nm in pairs(animKeybinds) do
						if nm == anim.name and kc ~= input.KeyCode then
							animKeybinds[kc] = nil
						end
					end
					waitingForBind = nil
					keyL.Text = keyName(input.KeyCode)
					keyL.TextColor3 = T.gold
					bindBtn.Text = "Bind"
					pcall(saveCyrisConfig)
					conn:Disconnect()
				end)
			end)

			clearBtn.MouseButton1Click:Connect(function()
				for kc, nm in pairs(animKeybinds) do
					if nm == anim.name then
						animKeybinds[kc] = nil
					end
				end
				keyL.Text = "None"
				keyL.TextColor3 = T.dim
				pcall(saveCyrisConfig)
			end)
		end
	end
	refreshBinds()

	animsTab.MouseButton1Click:Connect(function() setActiveTab("Anims") end)
	statesTab.MouseButton1Click:Connect(function() setActiveTab("States") end)
	speedTab.MouseButton1Click:Connect(function() setActiveTab("Speed") end)
	importTab.MouseButton1Click:Connect(function() setActiveTab("Import") end)
	bindsTab.MouseButton1Click:Connect(function()
		refreshBinds()
		setActiveTab("Binds")
	end)
	setActiveTab("Anims")

	-- Bottom controls
	local controls = Instance.new("Frame")
	controls.Size = UDim2.new(1, -24, 0, 48)
	controls.Position = UDim2.new(0, 12, 1, -60)
	controls.BackgroundTransparency = 1
	controls.Parent = main

	local playBtn = Instance.new("TextButton")
	playBtn.Name = "PlayBtn"
	playBtn.Size = UDim2.new(0.62, -4, 1, 0)
	playBtn.BackgroundColor3 = T.accent
	playBtn.Text = reanimActive and "Stop" or "Play"
	playBtn.TextColor3 = Color3.new(1,1,1)
	playBtn.Font = Enum.Font.GothamBlack
	playBtn.TextSize = 15
	playBtn.Parent = controls
	corner(playBtn, 10)
	stroke(playBtn, Color3.fromRGB(255, 255, 255), 1)

	local stopBtn = Instance.new("TextButton")
	stopBtn.Name = "StopBtn"
	stopBtn.Size = UDim2.new(0.38, -4, 1, 0)
	stopBtn.Position = UDim2.new(0.62, 4, 0, 0)
	stopBtn.BackgroundColor3 = T.button
	stopBtn.Text = "Kill"
	stopBtn.TextColor3 = T.text
	stopBtn.Font = Enum.Font.GothamBold
	stopBtn.TextSize = 14
	stopBtn.Parent = controls
	corner(stopBtn, 10)

	playBtn.MouseButton1Click:Connect(function()
		if reanimActive then
			stopReanimation(true)
			playBtn.Text = "Play"
			status.Text = "Idle  ·  None"
			status.TextColor3 = T.dim
			statusDot.BackgroundColor3 = T.dim
		else
			local name = selectedAnim
			local ok = false
			if name then
				ok = playByName(name)
			else
				-- No selection: run Idle/Run/Jump state machine
				ok = startStateMachine()
			end
			if ok then
				playBtn.Text = "Stop"
				status.Text = "Playing  ·  " .. currentAnimName
				status.TextColor3 = T.green
				statusDot.BackgroundColor3 = T.green
			else
				status.Text = "Failed  ·  check console"
				status.TextColor3 = T.accent
			end
		end
	end)

	stopBtn.MouseButton1Click:Connect(function()
		stopReanimation(true)
		playBtn.Text = "Play"
		status.Text = "Idle  ·  None"
		status.TextColor3 = T.dim
		statusDot.BackgroundColor3 = T.dim
	end)

	-- Drag
	do
		local dragging, dragStart, startPos = false, nil, nil
		header.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = true
				dragStart = input.Position
				startPos = main.Position
			end
		end)
		UserInputService.InputChanged:Connect(function(input)
			if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
				local d = input.Position - dragStart
				main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
			end
		end)
		UserInputService.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = false
			end
		end)
	end
end

function toggleReanimation()
	if reanimActive then
		stopReanimation()
	else
		startStateMachine()
		createReanimMenu()
	end
end

-- Global keybind listener for reanimation emotes + speed + custom states
if not keybindConn then
	keybindConn = UserInputService.InputBegan:Connect(function(input, processed)
		if processed then return end
		if waitingForBind or waitingForSpeedBind or waitingForStateBind then return end
		if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
		-- Speed binds
		local spd = speedKeybinds[input.KeyCode]
		if spd then
			reanimSpeed = spd
			if reanimGui then
				local sv = reanimGui:FindFirstChild("SpeedVal", true)
				if sv then sv.Text = string.format("%.2fx", reanimSpeed) end
			end
			return
		end
		-- Custom state binds (toggle)
		for _, cs in ipairs(customStates) do
			if cs.keyCode == input.KeyCode then
				if not reanimActive then
					startStateMachine()
				end
				if activeCustomState == cs.name then
					activeCustomState = nil
					reanimStartTime = os.clock()
				else
					activeCustomState = cs.name
					reanimStartTime = os.clock()
					currentMode = "states"
					if not reanimConn then
						startStep("states")
					end
				end
				return
			end
		end
		local animName = animKeybinds[input.KeyCode]
		if not animName then return end
		if reanimActive and currentAnimName == animName then
			stopReanimation(true)
		else
			playByName(animName)
		end
	end)
end

-- ==================== NAMETAG ====================
-- Animated pill tag above head (orbiting border, shine sweep, glitch, ash). Default = whoever executes the script.
local function clearNametag()
	if nametagGui then
		pcall(function() nametagGui:Destroy() end)
		nametagGui = nil
	end
end

updateNametag = function()
	clearNametag()
	if not nametagEnabled then return end
	local character = LocalPlayer.Character
	if not character then return end
	local head = nil
	if reanimClone and reanimClone.Parent then
		head = reanimClone:FindFirstChild("Head")
	end
	if not head then
		head = character:FindFirstChild("Head")
	end
	if not head then return end

	local display = (type(nametagText) == "string" and nametagText ~= "" and nametagText)
		or LocalPlayer.DisplayName
		or LocalPlayer.Name

	local WHITE = Color3.fromRGB(255, 255, 255)
	local BLACK = Color3.fromRGB(0, 0, 0)

	-- ===== sizing: slim pill that hugs the name =====
	local PLATE_H = 34                                  -- slimmer than before (was 44)
	local textW = math.clamp(#display * 15, 70, 320)    -- bigger text, tag grows with the name
	local plateW = textW + 76
	local LINE = 46                                     -- side flare length
	local W = plateW + (LINE + 16) * 2
	local H = 84
	local PLATE_Y = 0.62                                -- plate center (fraction of height); room above for ash

	local bb = Instance.new("BillboardGui")
	bb.Name = "CyrisNametag"
	bb.Size = UDim2.new(0, W, 0, H)
	bb.StudsOffset = Vector3.new(0, 3.1, 0)
	bb.AlwaysOnTop = true
	bb.MaxDistance = 150
	bb.LightInfluence = 0
	bb.Parent = head
	nametagGui = bb

	-- ===== thin outer ring =====
	local ring = Instance.new("Frame")
	ring.Name = "Ring"
	ring.AnchorPoint = Vector2.new(0.5, 0.5)
	ring.Position = UDim2.new(0.5, 0, PLATE_Y, 0)
	ring.Size = UDim2.new(0, plateW + 8, 0, PLATE_H + 8)
	ring.BackgroundTransparency = 1
	ring.ZIndex = 1
	ring.Parent = bb
	local rc = Instance.new("UICorner")
	rc.CornerRadius = UDim.new(1, 0)
	rc.Parent = ring
	local rs = Instance.new("UIStroke")
	rs.Color = Color3.fromRGB(210, 210, 210)
	rs.Thickness = 1
	rs.Transparency = 0.65
	rs.Parent = ring

	-- ===== main plate (pill) =====
	local plate = Instance.new("Frame")
	plate.Name = "Plate"
	plate.AnchorPoint = Vector2.new(0.5, 0.5)
	plate.Position = UDim2.new(0.5, 0, PLATE_Y, 0)
	plate.Size = UDim2.new(0, plateW, 0, PLATE_H)
	plate.BackgroundColor3 = Color3.fromRGB(6, 6, 6)
	plate.BackgroundTransparency = 0.05
	plate.BorderSizePixel = 0
	plate.ClipsDescendants = true
	plate.ZIndex = 2
	plate.Parent = bb
	local pc = Instance.new("UICorner")
	pc.CornerRadius = UDim.new(1, 0)
	pc.Parent = plate

	-- animated border: a bright streak circles the pill
	local ps = Instance.new("UIStroke")
	ps.Color = WHITE
	ps.Thickness = 2
	ps.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	ps.Parent = plate
	local psg = Instance.new("UIGradient")
	psg.Transparency = NumberSequence.new{
		NumberSequenceKeypoint.new(0, 0.85),
		NumberSequenceKeypoint.new(0.35, 0.85),
		NumberSequenceKeypoint.new(0.5, 0),
		NumberSequenceKeypoint.new(0.65, 0.85),
		NumberSequenceKeypoint.new(1, 0.85),
	}
	psg.Parent = ps

	-- anime art cropped to a thin band across the eyes
	if CYRIS_ANIME_BG then
		local rectH = math.max(20, 500 * PLATE_H / plateW)
		local nbg = Instance.new("ImageLabel")
		nbg.Name = "TagBG"
		nbg.Size = UDim2.new(1, 0, 1, 0)
		nbg.BackgroundTransparency = 1
		nbg.Image = CYRIS_ANIME_BG
		nbg.ImageTransparency = 0
		nbg.ScaleType = Enum.ScaleType.Stretch
		nbg.ImageRectSize = Vector2.new(500, rectH)
		nbg.ImageRectOffset = Vector2.new(0, math.max(0, 185 - rectH / 2))
		nbg.ZIndex = 1
		nbg.Parent = plate
	end

	-- dark center so the white name always reads, lighter toward the tips
	local shade = Instance.new("Frame")
	shade.Name = "Shade"
	shade.Size = UDim2.new(1, 0, 1, 0)
	shade.BackgroundColor3 = BLACK
	shade.BorderSizePixel = 0
	shade.ZIndex = 2
	shade.Parent = plate
	local shg = Instance.new("UIGradient")
	shg.Transparency = NumberSequence.new{
		NumberSequenceKeypoint.new(0, 0.82),
		NumberSequenceKeypoint.new(0.5, 0.58),
		NumberSequenceKeypoint.new(1, 0.82),
	}
	shg.Parent = shade

	-- shine sweep
	local shine = Instance.new("Frame")
	shine.Name = "Shine"
	shine.Size = UDim2.new(1, 0, 1, 0)
	shine.BackgroundColor3 = WHITE
	shine.BorderSizePixel = 0
	shine.ZIndex = 3
	shine.Parent = plate
	local sg = Instance.new("UIGradient")
	sg.Rotation = 20
	sg.Offset = Vector2.new(-1, 0)
	sg.Transparency = NumberSequence.new{
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(0.42, 1),
		NumberSequenceKeypoint.new(0.5, 0.7),
		NumberSequenceKeypoint.new(0.58, 1),
		NumberSequenceKeypoint.new(1, 1),
	}
	sg.Parent = shine

	-- diamond studs inside the tips
	local function diamond(parent, pos, size, z)
		local d = Instance.new("Frame")
		d.AnchorPoint = Vector2.new(0.5, 0.5)
		d.Position = pos
		d.Size = UDim2.new(0, size, 0, size)
		d.Rotation = 45
		d.BackgroundColor3 = WHITE
		d.BorderSizePixel = 0
		d.ZIndex = z
		d.Parent = parent
		return d
	end
	diamond(plate, UDim2.new(0, 22, 0.5, 0), 8, 5)
	diamond(plate, UDim2.new(1, -22, 0.5, 0), 8, 5)

	-- ===== name (with glitch ghosts behind it) =====
	local label = Instance.new("TextLabel")
	label.Name = "TagText"
	label.Size = UDim2.new(1, -60, 1, 0)
	label.Position = UDim2.new(0, 30, 0, 0)
	label.BackgroundTransparency = 1
	label.Text = display
	label.TextColor3 = WHITE
	label.TextStrokeTransparency = 0.3
	label.TextStrokeColor3 = BLACK
	label.Font = Enum.Font.GothamBlack
	label.TextScaled = true
	label.TextXAlignment = Enum.TextXAlignment.Center
	label.ZIndex = 6
	local ts = Instance.new("UITextSizeConstraint")
	ts.MinTextSize = 12
	ts.MaxTextSize = 24
	ts.Parent = label

	local ghostA = label:Clone()
	ghostA.Name = "GhostA"
	ghostA.TextColor3 = Color3.fromRGB(205, 205, 205)
	ghostA.TextTransparency = 1
	ghostA.TextStrokeTransparency = 1
	ghostA.ZIndex = 4
	ghostA.Parent = plate
	local ghostB = label:Clone()
	ghostB.Name = "GhostB"
	ghostB.TextColor3 = Color3.fromRGB(110, 110, 110)
	ghostB.TextTransparency = 1
	ghostB.TextStrokeTransparency = 1
	ghostB.ZIndex = 4
	ghostB.Parent = plate
	label.Parent = plate

	-- ===== side flares: fading lines + tip diamonds =====
	local function flare(isLeft)
		local line = Instance.new("Frame")
		line.AnchorPoint = Vector2.new(isLeft and 1 or 0, 0.5)
		local edge = plateW / 2 + 8
		line.Position = UDim2.new(0.5, isLeft and -edge or edge, PLATE_Y, 0)
		line.Size = UDim2.new(0, LINE, 0, 2)
		line.BackgroundColor3 = WHITE
		line.BorderSizePixel = 0
		line.ZIndex = 2
		line.Parent = bb
		local g = Instance.new("UIGradient")
		g.Transparency = isLeft
			and NumberSequence.new(1, 0.05)
			or NumberSequence.new(0.05, 1)
		g.Parent = line
		local tipX = isLeft and -(edge + LINE) or (edge + LINE)
		diamond(bb, UDim2.new(0.5, tipX, PLATE_Y, 0), 5, 2)
	end
	flare(true)
	flare(false)

	-- ===== underline glow =====
	local under = Instance.new("Frame")
	under.Name = "Underline"
	under.AnchorPoint = Vector2.new(0.5, 0)
	under.Position = UDim2.new(0.5, 0, PLATE_Y, PLATE_H / 2 + 9)
	under.Size = UDim2.new(0, plateW * 0.55, 0, 2)
	under.BackgroundColor3 = WHITE
	under.BorderSizePixel = 0
	under.ZIndex = 2
	under.Parent = bb
	local ug = Instance.new("UIGradient")
	ug.Transparency = NumberSequence.new{
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(0.5, 0),
		NumberSequenceKeypoint.new(1, 1),
	}
	ug.Parent = under

	-- ===== rising ash motes =====
	local motes = {}
	for i = 1, 8 do
		local sz = (i % 2 == 0) and 3 or 2
		local m = Instance.new("Frame")
		m.Size = UDim2.new(0, sz, 0, sz)
		m.AnchorPoint = Vector2.new(0.5, 0.5)
		m.BackgroundColor3 = WHITE
		m.BorderSizePixel = 0
		m.BackgroundTransparency = 1
		m.ZIndex = 7
		m.Parent = bb
		local mc = Instance.new("UICorner")
		mc.CornerRadius = UDim.new(1, 0)
		mc.Parent = m
		motes[i] = {
			f = m,
			x = 0.14 + 0.72 * ((i * 0.6180339) % 1),
			speed = 0.2 + (i % 3) * 0.08,
			off = i / 8,
			sway = 5 + (i % 4) * 2,
		}
	end

	-- ===== animation loop (stops itself when the tag is destroyed) =====
	local t0 = os.clock()
	local plateTop = PLATE_Y * H - PLATE_H / 2
	local conn
	conn = RunService.RenderStepped:Connect(function()
		if not bb.Parent then
			conn:Disconnect()
			return
		end
		local t = os.clock() - t0

		-- gentle float
		bb.StudsOffset = Vector3.new(0, 3.1 + math.sin(t * 1.8) * 0.1, 0)

		-- border streak orbit + ring/underline pulse
		psg.Rotation = (t * 110) % 360
		rs.Transparency = 0.6 + 0.25 * math.sin(t * 2)
		under.BackgroundTransparency = 0.1 + 0.3 * (0.5 + 0.5 * math.sin(t * 2.4))

		-- shine sweeps across every few seconds
		local p = (t % 3.8) / 1.2
		if p < 1 then
			sg.Offset = Vector2.new(-1 + 2 * p, 0)
		else
			sg.Offset = Vector2.new(-1, 0)
		end

		-- brief RGB-style glitch burst
		local gt = t % 4.6
		if gt < 0.16 then
			local ox = math.random(-4, 4)
			local oy = math.random(-1, 1)
			ghostA.Position = UDim2.new(0, 30 - ox - 2, 0, oy)
			ghostB.Position = UDim2.new(0, 30 + ox + 2, 0, -oy)
			ghostA.TextTransparency = 0.3
			ghostB.TextTransparency = 0.45
		else
			ghostA.TextTransparency = 1
			ghostB.TextTransparency = 1
		end

		-- ash motes drift up and fade
		for i, mo in ipairs(motes) do
			local ph = (t * mo.speed + mo.off) % 1
			mo.f.Position = UDim2.new(mo.x, math.sin(t * 2 + i) * mo.sway * ph, 0, plateTop + 2 - ph * (plateTop - 2))
			mo.f.BackgroundTransparency = 1 - math.sin(ph * math.pi) * 0.85
		end
	end)
end

setNametag = function(text)
	if type(text) ~= "string" then return end
	text = text:gsub("^%s+", ""):gsub("%s+$", "")
	if text == "" then return end
	-- "default" / "none" / "reset" restores the executor's real name
	local low = string.lower(text)
	if low == "default" or low == "none" or low == "reset" or low == "me" then
		nametagText = (LocalPlayer.DisplayName and LocalPlayer.DisplayName ~= "" and LocalPlayer.DisplayName) or LocalPlayer.Name
	else
		nametagText = text
	end
	nametagEnabled = true
	waitingForNametag = false
	updateNametag()
	pcall(saveCyrisConfig)
	if reanimGui then
		local box = reanimGui:FindFirstChild("NametagBox", true)
		if box and box:IsA("TextBox") then
			box.Text = nametagText
		end
	end
end

resetNametagToDefault = function()
	nametagText = (LocalPlayer.DisplayName and LocalPlayer.DisplayName ~= "" and LocalPlayer.DisplayName) or LocalPlayer.Name
	nametagEnabled = true
	waitingForNametag = false
	updateNametag()
	pcall(saveCyrisConfig)
	if reanimGui then
		local box = reanimGui:FindFirstChild("NametagBox", true)
		if box and box:IsA("TextBox") then
			box.Text = nametagText
		end
	end
end

do
	local prev = aioHandle
	aioHandle = function(speaker, text)
		if prev(speaker, text) then return true end
		if type(text) ~= "string" then return false end
		if text:find("CYRIS: Playing") or text:find("CYRIS: Reanimation") then
			return false
		end
		local lower = string.lower(text):gsub("^%s+", ""):gsub("%s+$", "")
		-- Only the person who executed the script can control their own nametag / reanim
		if speaker ~= LocalPlayer then return false end

		-- Conversational nametag: after "change it to what master..." capture next message
		if waitingForNametag then
			waitingForNametag = false
			-- ignore if they typed another command instead
			if lower:find("^cyris") or lower == "reanim" or lower == "nametag" then
				-- fall through to other handlers
			else
				local original = text:gsub("^%s+", ""):gsub("%s+$", "")
				setNametag(original)
				sendChat("CYRIS: Tag rewritten, master. You are now \"" .. nametagText .. "\".")
				return true
			end
		end

		if lower == "cyris reanim" or lower == "reanim" then
			task.spawn(createReanimMenu)
			return true
		end
		if lower:find("^cyris%s+reanim%s+stop") or lower == "stop reanim" then
			task.spawn(function() stopReanimation() end)
			return true
		end
		if lower:find("^cyris%s+reanim%s+menu") then
			task.spawn(createReanimMenu)
			return true
		end

		-- Direct set: "cyris nametag <text>" or "nametag <text>"
		local nt = lower:match("^cyris%s+nametag%s+(.+)$") or lower:match("^nametag%s+(.+)$")
		if nt then
			local original = text:gsub("^%s+", ""):gsub("%s+$", "")
			local raw = original:match("^[Nn]ametag%s+(.+)$") or original:match("^[Ww]endigo%s+[Nn]ametag%s+(.+)$")
			setNametag(raw or nt)
			sendChat("CYRIS: Tag set to \"" .. nametagText .. "\".")
			return true
		end

		-- Conversational prompt triggers (owner only)
		local changeTriggers = {
			"^cyris%s+change%s+username%s+tag",
			"^cyris%s+change%s+nametag",
			"^cyris%s+change%s+name%s+tag",
			"^cyris%s+change%s+tag",
			"^cyris%s+username%s+tag",
			"^change%s+username%s+tag",
			"^change%s+nametag",
			"^cyris%s+nametag$",
			"^nametag$",
		}
		for _, pat in ipairs(changeTriggers) do
			if lower:match(pat) then
				waitingForNametag = true
				sendChat("CYRIS: change it to what master....")
				return true
			end
		end

		if lower == "cyris nametag default" or lower == "nametag default" or lower == "cyris reset nametag" then
			resetNametagToDefault()
			sendChat("CYRIS: Tag restored to " .. nametagText .. ".")
			return true
		end

		return false
	end
end

