local function createCyrisMenu()
    -- ============================================================
    -- LOCAL IMAGE LOADING (no Roblox upload needed)
    -- Put GIFs / images in the SAME FOLDER as this script.
    -- Works with getcustomasset (Synapse, Wave, Solara, Fluxus, etc.)
    -- ============================================================
    local function loadLocal(path)
        if type(path) ~= "string" or path == "" then return nil end
        path = path:gsub("^%s+", ""):gsub("%s+$", "")
        -- already an asset id / rbxasset
        if path:find("^rbxasset") or path:find("^%d+$") then
            if path:find("^%d+$") then return "rbxassetid://" .. path end
            return path
        end
        local candidates = {
            path,
            path:gsub("\\", "/"),
            "workspace/" .. path,
            "Workspace/" .. path,
            "images/" .. path,
            "Images/" .. path,
            "assets/" .. path,
        }
        -- also try just the filename if a full path was given
        local fname = path:match("([^/\\]+)$")
        if fname and fname ~= path then
            table.insert(candidates, fname)
            table.insert(candidates, "workspace/" .. fname)
        end
        local loaders = {}
        if getcustomasset then table.insert(loaders, getcustomasset) end
        if syn and syn.getcustomasset then table.insert(loaders, syn.getcustomasset) end
        if getasset then table.insert(loaders, getasset) end
        if isfile and readfile and getcustomasset then
            -- some executors need the file written to a temp cache first
            table.insert(loaders, function(p)
                if isfile(p) then return getcustomasset(p) end
                return nil
            end)
        end
        for _, candidate in ipairs(candidates) do
            for _, loader in ipairs(loaders) do
                local ok, result = pcall(loader, candidate)
                if ok and type(result) == "string" and result ~= "" and result ~= "rbxassetid://0" then
                    return result
                end
            end
        end
        warn("[CYRIS] Could not load local image: " .. tostring(path))
        warn("[CYRIS] Put the file in your executor workspace folder and use just the filename.")
        return nil
    end

    -- Embedded anime girl bg (your pink-haired character) — always preferred
    local LOADING_IMAGE = CYRIS_ANIME_BG or loadLocal("cyris_bg.jpg") or loadLocal("cyris_bg.gif") or loadLocal("cyris_bg.png") or "rbxassetid://0"
