    local function runCommand(entry)
        local cmd = entry[2]
        if entry[3] then
            local t = targetBox.Text:gsub("^%s+", ""):gsub("%s+$", "")
            if t == "" then
                sendChat("CYRIS: Name a vessel first...")
                return
            end
            cmd = string.format(cmd, t)
        end
        -- 1) exact aioHandle commands (cry, wonk, light up, reanim, etc.)
        local ok1, handled1 = pcall(function()
            return aioHandle(LocalPlayer, cmd)
        end)
        if ok1 and handled1 then return end

        -- 2) prefix with "cyris " so getReply / onChatted path works
        local msg = cmd
        if not string.lower(msg):find("cyris") then
            msg = "cyris " .. msg
        end
        local ok2, handled2 = pcall(function()
            return aioHandle(LocalPlayer, msg)
        end)
        if ok2 and handled2 then return end

        -- 3) bulk admin commands live in getReply (fly, noclip, god mode, ...)
        local ok3, reply = pcall(function()
            return getReply(msg, LocalPlayer)
        end)
        if ok3 and type(reply) == "string" and #reply > 0 then
            sendChat(reply)
        end
    end

    local function rebuild()
        for _, c in ipairs(scroll:GetChildren()) do
            if c:IsA("TextButton") then c:Destroy() end
        end
        local cat = CATEGORIES[currentTab]
        if not cat then return end
        local filter = searchBox.Text:lower()
        for _, entry in ipairs(cat[2]) do
            local name = entry[1]
            if filter == "" or name:lower():find(filter, 1, true) then
                local btn = Instance.new("TextButton")
                btn.BackgroundColor3 = THEME.button
                btn.BackgroundTransparency = 0.55
                btn.Text = name
                btn.TextColor3 = THEME.text
                btn.TextSize = 13
                btn.Font = Enum.Font.GothamMedium
                btn.AutoButtonColor = false
                btn.ZIndex = 6
                btn.Parent = scroll
                round(btn, 8)
                stroke(btn, THEME.border, 1)
                btn.MouseEnter:Connect(function()
                    TweenService:Create(btn, TweenInfo.new(0.15), {BackgroundColor3 = THEME.hover}):Play()
                end)
                btn.MouseLeave:Connect(function()
                    TweenService:Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = THEME.button}):Play()
                end)
                btn.MouseButton1Click:Connect(function()
                    TweenService:Create(btn, TweenInfo.new(0.08), {BackgroundColor3 = THEME.accent}):Play()
                    task.delay(0.12, function()
                        TweenService:Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = THEME.button}):Play()
                    end)
                    runCommand(entry)
                end)
            end
        end
    end

    local function selectTab(i)
        currentTab = i
        searchBox.Text = ""
        for idx, tb in ipairs(tabButtons) do
            local active = idx == i
            TweenService:Create(tb, TweenInfo.new(0.2), {
                BackgroundColor3 = active and THEME.accent or THEME.card,
                TextColor3 = active and Color3.new(1, 1, 1) or THEME.dim,
            }):Play()
        end
        rebuild()
    end

    for i, cat in ipairs(CATEGORIES) do
        local tb = Instance.new("TextButton")
        tb.Size = UDim2.new(0, 88, 1, 0)
        tb.BackgroundColor3 = THEME.card
        tb.BackgroundTransparency = 0.5
        tb.Text = cat[1]
        tb.TextColor3 = THEME.dim
        tb.TextSize = 12
        tb.Font = Enum.Font.GothamBold
        tb.AutoButtonColor = false
        tb.ZIndex = 6
        tb.Parent = tabBar
        round(tb, 8)
        tabButtons[i] = tb
        tb.MouseButton1Click:Connect(function() selectTab(i) end)
    end

    -- Background button in header
    local bgBtn = Instance.new("TextButton")
    bgBtn.Size = UDim2.new(0, 28, 0, 28)
    bgBtn.Position = UDim2.new(1, -78, 0.5, -14)
    bgBtn.BackgroundColor3 = THEME.button
    bgBtn.Text = "BG"
    bgBtn.TextColor3 = THEME.dim
    bgBtn.TextSize = 11
    bgBtn.Font = Enum.Font.GothamBold
    bgBtn.AutoButtonColor = false
    bgBtn.ZIndex = 6
    bgBtn.Parent = header
    round(bgBtn, 6)
    bgBtn.MouseButton1Click:Connect(function()
        bgPanel.Visible = not bgPanel.Visible
    end)

    searchBox:GetPropertyChangedSignal("Text"):Connect(rebuild)
    selectTab(4) -- default to Cyris tab


    -- Drag whole menu from header
    do
        local dragging, dragStart, startPos = false, nil, nil
        header.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = main.Position
            end
        end)
        header.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local d = input.Position - dragStart
                main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
            end
        end)
        UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end)
    end

    -- open / close
    local OPEN_SIZE = UDim2.new(0, 380, 0, 480)
    local isOpen = false

    local function openMenu()
        isOpen = true
        main.Visible = true
        TweenService:Create(main, TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {Size = OPEN_SIZE}):Play()
    end
    local function closeMenu()
        isOpen = false
        bgPanel.Visible = false
        local t = TweenService:Create(main, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.In),
            {Size = UDim2.new(0, 0, 0, 0)})
        t:Play()
        t.Completed:Connect(function()
            if not isOpen then main.Visible = false end
        end)
    end

    closeBtn.MouseButton1Click:Connect(closeMenu)
    UserInputService.InputBegan:Connect(function(input, processed)
        if processed then return end
        if input.KeyCode == Enum.KeyCode.Quote then
            if isOpen then closeMenu() else openMenu() end
        end
    end)

    task.delay(1.6, openMenu)
end


