-- ==================== UNIFIED DISPATCH ====================
-- Every chat message goes through here exactly once:
--   1. ignore Cyris's own output (prevents self-reply loops)
--   2. blacklist + all-in-one commands (cry, wonk, sacrifice, ...)
--   3. anything not handled falls through to the original "cyris ..." engine
local function dispatch(speaker, text)
	if not speaker or type(text) ~= "string" then return end

	if speaker == LocalPlayer then
		local sentAt = botSent[text]
		if sentAt and os.clock() - sentAt < 10 then return end
	end

	if aioHandle(speaker, text) then return end
	onChatted(speaker, text)
end

-- CONNECTIONS (one listener set, so nothing fires twice)
local function hookLegacy(player)
	player.Chatted:Connect(function(msg) dispatch(player, msg) end)
end
local chatOk, chatErr = pcall(function()
	local useNew = false
	pcall(function()
		if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
			useNew = true
		end
	end)
	if useNew then
		TextChatService.MessageReceived:Connect(function(message)
			local source = message.TextSource
			if not source then return end
			dispatch(Players:GetPlayerByUserId(source.UserId), message.Text)
		end)
		print("[CYRIS] TextChatService connected")
	else
		for _, player in pairs(Players:GetPlayers()) do hookLegacy(player) end
		Players.PlayerAdded:Connect(hookLegacy)
		print("[CYRIS] Legacy chat connected")
	end
end)
if not chatOk then
	warn("[CYRIS] Chat connect failed: " .. tostring(chatErr) .. " — falling back to legacy")
	pcall(function()
		for _, player in pairs(Players:GetPlayers()) do hookLegacy(player) end
		Players.PlayerAdded:Connect(hookLegacy)
	end)
end

LocalPlayer.CharacterAdded:Connect(function()
    if flying then stopFlying() end
    removeClones()
    if attachConnection then stopAttaching() end
    if sitConnection then stopSitting() end
    if crackConnection then 
        crackConnection:Disconnect()
        crackConnection = nil
        crackTargetPlayer = nil
    end
    if tornadoConnection then
        tornadoConnection:Disconnect()
        tornadoConnection = nil
        tornadoTarget = nil
    end
    if noclipConnection then noclipConnection:Disconnect() noclipConnection = nil end
    if godModeConnection then godModeConnection:Disconnect() godModeConnection = nil end
    if shieldBubble then shieldBubble:Destroy() shieldBubble = nil end
    if eventData then
        if eventData.model then eventData.model:Destroy() end
        if eventData.sound then eventData.sound:Destroy() end
        if eventData.connection then eventData.connection:Disconnect() end
        eventData = nil
    end
    if crossData then
        if crossData.model then crossData.model:Destroy() end
        if crossData.connection then crossData.connection:Disconnect() end
        crossData = nil  
    end
end)
 
